window.KRONOLOJI_COK_ISPANYA = [
{ t:"1273-01-21", gun:"29 Cemâziyelâhir 671 / 21 Ocak 1273 — TDV'de tam gün (I. Muhammed'in ölümü)", b:"I. Muhammed öldü, oğlu II. Muhammed el-Fakīh tahta geçti", tur:"hukumdar", onem:3, dunya:1, kapsam:"ic", etiket:["hukumdar","nasri-sultanlari","konu-siyasi"], yer_id:"Granada", devlet:"granada", d:"Nasrî Devleti'nin kurucusu Gālib-Billâh I. Muhammed 21 Ocak 1273'te öldü; yerine ilmiyle tanındığı için 'Fakīh' diye anılan oğlu II. Muhammed geçti. Otuz yıla yaklaşan saltanatında devletin merkez ve taşra teşkilâtı ile vergi düzeni kuruldu.", kaynak:"TDV `nasriler` (İsmail Yiğit, 2006, DİA 32:420-424)" },
{ t:"1284-04-04", gun:"4 Nisan 1284 (X. Alfonso'nun Sevilla'da ölümü; RAH)", b:"X. Alfonso öldü, IV. Sancho Kastilya tahtına geçti", tur:"hukumdar", onem:4, dunya:1, kapsam:"ic", etiket:["hukumdar","kastilya-taht","konu-siyasi"], yer_id:"", odak_kimlik:["kastilya"], devlet:"kastilya", d:"Babasına isyan ederek onu fiilen iktidardan uzaklaştırmış olan infante Sancho, X. Alfonso'nun Sevilla'da ölümüyle IV. Sancho adıyla kral oldu ve Toledo katedralinde törenle taç giydi. Aynı yıl Sevilla ve Valladolid'de Cortes toplayarak meşruiyetini pekiştirmeye çalıştı. Ancak la Cerda yeğenlerinin taht iddiası, saltanatı boyunca iç ve dış çatışmaların kaynağı olarak kaldı.", kaynak:"J. M. Nieto Soria, \"Sancho IV\", Real Academia de la Historia, Diccionario Biográfico Español (historia-hispanica.rah.es/biografias/41322)" },
{ t:"1284-08-16", gun:"16 Ağustos 1284 (RAH)", b:"I. Juana, Fransız veliahdı Philippe ile evlendi — Navarra Fransız tacına bağlandı", tur:"hanedan", onem:5, dunya:2, kapsam:"dis", etiket:["hanedan","navarra-fransa-birligi","konu-siyasi"], yer_id:"Pamplona", devletler:["navarra","fransa"], d:"Babası I. Enrique'nin 1274'teki ölümüyle bir yaşında Navarra ve Şampanya'nın vârisi olan Juana, Kastilya ve Aragon'un baskısından korunmak için Fransız sarayına emanet edilmiş; krallığın yönetimi 1275'ten beri fiilen Fransa'daydı. Veliaht Philippe (IV. Philippe) ile evliliğinden sonra çift Navarra'yı birlikte yönetti ve ertesi yıl Fransa'nın da hükümdarı oldu; Navarra 1328'e dek Fransız krallarınca uzaktan valilerle yönetildi.", kaynak:"J. Carrasco Pérez, \"Juana I de Navarra y de Francia\", RAH DB~e (biografias/24946)" },
{ t:"1285-01-01", gun:"yalnız yıl (TDV '1285'); gün kaynakta yok", b:"Hafsî Tunus ile on beş yıllık antlaşma", tur:"antlasma", onem:2, dunya:1, kapsam:"dis", etiket:["antlasma","hafsi-iliskileri","konu-siyasi"], yer_id:"Tunus", devletler:["aragon","hafsi"], d:"Hafsî sultanı Ebû Hafs Ömer, Aragon kralı III. Pedro ile on beş yıl geçerli bir antlaşma imzaladı. Hafsî topraklarındaki Hıristiyanlara dinî ve ticarî imtiyazlar tanındı ve Tunus, Aragon'a her yıl belirli bir vergi ödemeyi kabul etti. Sicilya'yı yeni almış olan Aragon, böylece Tunus kıyısı üzerinde de nüfuz kurdu.", kaynak:"TDV `aragon` (İA, 1991) — 'on beş yıllık bir anlaşma imzaladı (1285)'" },
{ t:"1285-09-04", gun:"3-4 Eylül 1285 gecesi/günü (GEC); 4'ü seçildi", b:"Formigues deniz zaferi — Fransız haçlı donanması dağıtıldı", tur:"savas", onem:4, dunya:2, kapsam:"dis", etiket:["savas","aragon-hacli-seferi","konu-askeri"], yer_id:"", odak_kimlik:["aragon","fransa"], devletler:["aragon","fransa"], d:"Papa IV. Martinus'un Sicilya'yı aldığı için tahttan düşürdüğü III. Pedro'ya karşı Fransa kralı III. Philippe 'haçlı seferi' adıyla Katalonya'yı istila etmiş, Girona'yı kuşatmıştı. Sicilya'dan gelen Roger de Lauria komutasındaki Katalan donanması Empordà kıyısında (Formigues adaları/Roses körfezi) Fransız donanmasını yendi. İkmal hattı kesilen istila ordusunun çöküşü bu zaferle başladı.", kaynak:"Gran Enciclopèdia Catalana, `croada-contra-catalunya` ve `pere-ii-de-catalunya-arago`" },
{ t:"1285-10-01", gun:"1 Ekim 1285 (GEC)", b:"Panissars geçidinde Fransız artçısının imhası — haçlı seferinin sonu", tur:"savas", onem:4, dunya:2, kapsam:"dis", etiket:["savas","aragon-hacli-seferi","konu-askeri"], yer_id:"", odak_kimlik:["aragon","fransa"], devletler:["aragon","fransa"], d:"Girona'yı ele geçirmesine rağmen salgın ve ikmal sıkıntısıyla çözülen Fransız ordusu Pireneler'e çekildi. Kral kafilesi geçerken dokunulmadı, ancak artçı Panissars geçidinde Katalan kuvvetlerince ezildi; III. Philippe dönüşte Perpignan'da öldü. Aragon, Papalık-Fransa ittifakına karşı hem ülkesini hem Sicilya'yı korumuş oldu.", kaynak:"Gran Enciclopèdia Catalana, `croada-contra-catalunya`" },
{ t:"1285-11-11", gun:"10'u 11'e bağlayan gece, 11 Kasım 1285 (GEC)", b:"III. Pedro'nun ölümü — III. Alfonso tahta, Sicilya ikinci oğul Jaime'ye", tur:"hukumdar", onem:3, dunya:1, kapsam:"ic", etiket:["hukumdar","barselona-hanedani","konu-siyasi"], yer_id:"", odak_kimlik:["aragon"], devlet:"aragon", d:"Fransız istilasını püskürten III. Pedro, Mayorka seferine giderken Vilafranca del Penedès'te hastalanıp öldü. Aragon, Katalonya ve Valensiya büyük oğlu III. Alfonso'ya geçti; Sicilya ise ayrı bir taç olarak ikinci oğlu Jaime'ye kaldı. Alfonso haberi, amcası Mayorka kralı II. Jaime'ye karşı yürüttüğü Balear seferinde aldı ve Mayorka ile İbiza'yı itaate aldı.", kaynak:"Gran Enciclopèdia Catalana, `pere-ii-de-catalunya-arago`, `alfons-ii-de-catalunya`" },
{ t:"1287-01-17", gun:"17 Ocak 1287 (Menorca Ada Konseyi'nin verdiği fetih günü); teslim antlaşması (Sant Agaiz) birkaç gün sonra", b:"Menorka'nın fethi — son Müslüman Balear adası alındı", tur:"fetih", onem:3, dunya:1, kapsam:"dis", etiket:["fetih","balear-adalari","konu-askeri"], yer_id:"", odak_kimlik:["aragon"], devlet:"aragon", d:"O güne dek Aragon'a vergi veren Müslüman bir emirlik olarak kalan Menorka'ya III. Alfonso çıkarma yaptı ve adayı kısa sürede ele geçirdi. Gerekçe, adanın yöneticisinin 1282'de III. Pedro'nun Kuzey Afrika seferini Tunus'a haber vermesiydi. Teslim şartlarıyla yalnız emir ve maiyeti adayı terk edebildi, halkın çoğu esir edildi; ada Hıristiyan iskânına açıldı.", kaynak:"Consell Insular de Menorca, 'La conquesta per Alfons III…' (cime.es IdPub=2200); Gran Enciclopèdia Catalana `alfons-ii-de-catalunya` (yıl ve gerekçe). TDV: Minorka/Menorka maddesi bulunamadı (slug 302)" },
{ t:"1288-06-08", gun:"8 Haziran 1288 (RAH)", b:"Alfaro olayı — gözde Lope Díaz de Haro kralın huzurunda öldürüldü", tur:"siyaset", onem:3, dunya:1, kapsam:"ic", etiket:["siyaset","kastilya-soylular","konu-siyasi"], yer_id:"", odak_kimlik:["kastilya"], devlet:"kastilya", d:"IV. Sancho'nun en güçlü gözdesi, Biskay senyörü Lope Díaz de Haro, Aragon ile ittifakı savunup Fransa yanlısı saray çevresiyle çatışınca Alfaro'daki danışma toplantısında kralla tartıştı ve kralın şövalyelerince öldürüldü; infante Juan hapsedildi. Olay Haro ailesini isyana ve Aragon'a yöneltti, kral ise danışman kadrosunu kilise adamlarıyla yeniledi.", kaynak:"J. M. Nieto Soria, \"Sancho IV\", RAH Diccionario Biográfico Español (biografias/41322)" },
{ t:"1291-06-18", gun:"18 Haziran 1291 (III. Alfonso'nun ölümü, GEC)", b:"III. Alfonso'nun ölümü — II. Jaime iki tacı birleştirdi", tur:"hukumdar", onem:3, dunya:1, kapsam:"ic", etiket:["hukumdar","barselona-hanedani","konu-siyasi"], yer_id:"", odak_kimlik:["aragon"], devlet:"aragon", d:"III. Alfonso Barselona'da varissiz öldü; taç, Sicilya kralı olan kardeşi II. Jaime'ye geçti. Jaime Ağustos 1291'de Barselona'ya gelip ant içti ve Sicilya tacını da elinde tuttu. Bu, Aragon'un Sicilya meselesinde Papalık ve Anjou'larla uzlaşmaya yönelmesinin başlangıcı oldu.", kaynak:"Gran Enciclopèdia Catalana, `alfons-ii-de-catalunya`, `jaume-ii-de-catalunya-arago`" },
{ t:"1292-01-01", gun:"yalnız yıl (1292); gün kaynaklarda doğrulanamadı", b:"IV. Sancho Tarîf'i (Tarifa) aldı", tur:"toprak-kazanc", onem:3, dunya:2, kapsam:"dis", etiket:["toprak-kazanc","bogaz-savasi","konu-askeri"], yer_id:"", odak_kimlik:["kastilya","granada"], devletler:["kastilya","granada"], d:"Merînîler karşısındaki yenilgilerin ardından Kastilya, Aragon donanmasının da desteğiyle karadan ve denizden kuşattığı Tarîf'i ele geçirdi; Cebelitârık Boğazı'nda Merînî geçişlerini denetleyen ilk büyük kazanımdı. Gırnata emîri II. Muhammed şehrin kendisine bırakılacağı şartıyla Kastilya'yı desteklemişti, ama kral şehri bırakmayınca emîr yeniden Merînîlere yöneldi.", kaynak:"TDV `nasriler` (Tarîf'in Kastilya kralınca alınıp bırakılmaması); J. M. Nieto Soria, \"Sancho IV\", RAH DB~e 41322 ('culminó con la toma de Tarifa', 1292)" },
{ t:"1293-01-01", gun:"yalnız yıl: 692/1293 (TDV `meriniler`); gün ve ay bilinmiyor. Tarîf'in Kastilya'ya düşüşünün kendi günü TDV'de yok", b:"Tarîf Kastilya'da kalınca II. Muhammed yeniden Merînîler'e döndü", tur:"ittifak", onem:3, dunya:1, kapsam:"dis", etiket:["ittifak","tarif","konu-siyasi"], yer_id:"Granada", devletler:["granada","merini","kastilya"], d:"II. Muhammed, Merînîler'in Endülüs'teki üslerinden çekindiği için Kastilya Kralı IV. Sancho ile anlaşmış, karşılığında alınacak Tarîf'in kendisine bırakılmasını ummuştu. Kastilyalılar şehri alıp teslim etmeyince Nasrî sultanı Fas'a gidip Merînîlerle ittifakı yeniledi. Olay, Boğaz kıyısının Nasrîler için kalıcı olarak daralmasının başlangıcıdır.", kaynak:"TDV `meriniler` (692/1293) · TDV `nasriler`" },
{ t:"1295-01-01", gun:"Haziran 1295 (GEC); gün kaynakta yok", b:"Anagni Antlaşması — Aragon Sicilya'dan vazgeçti", tur:"antlasma", onem:4, dunya:2, kapsam:"dis", etiket:["antlasma","sicilya-meselesi","konu-siyasi"], yer_id:"", odak_kimlik:["aragon","napoli"], devletler:["aragon","napoli"], d:"Papa VIII. Bonifatius'un aracılığıyla II. Jaime, Fransa ve Napoli ile barıştı: Sicilya'yı Kilise'ye bırakmayı, Napoli kralı II. Charles'ın kızı Blanca ile evlenmeyi kabul etti; aforoz ve kilise yasağı kaldırıldı, Valois'nın Aragon tacı iddiası düştü. Balear adaları Aragon'a tâbi olmak kaydıyla Mayorka kralına iade edildi. Sicilyalılar ise bu antlaşmayı tanımayıp Jaime'nin kardeşi Federico'yu kral yaptı.", kaynak:"Gran Enciclopèdia Catalana, `tractat-danagni`, `jaume-ii-de-catalunya-arago`" },
{ t:"1295-04-25", gun:"25 Nisan 1295 (RAH)", b:"IV. Sancho öldü — çocuk kral IV. Fernando, María de Molina'nın vesayetinde", tur:"hukumdar", onem:4, dunya:1, kapsam:"ic", etiket:["hukumdar","kastilya-taht","konu-siyasi"], yer_id:"", odak_kimlik:["kastilya"], devlet:"kastilya", d:"IV. Sancho Toledo'da veremden öldü; yerine dokuz yaşındaki oğlu IV. Fernando geçti ve vasiyet gereği annesi María de Molina vasi oldu. Çocuk kralın tahtı, la Cerda iddiası ve Aragon ile Portekiz'in müdahaleleri yüzünden yıllarca iç savaş tehdidi altında kaldı.", kaynak:"C. González Mínguez, \"Fernando IV\", RAH DB~e (biografias/16456); J. M. Nieto Soria, \"Sancho IV\", RAH DB~e 41322" },
{ t:"1296-01-01", gun:"yalnız yıl 1296 (GEC)", b:"Alicante, Elche ve Murcia'nın ele geçirilmesi", tur:"toprak-kazanc", onem:3, dunya:1, kapsam:"dis", etiket:["toprak-kazanc","murcia","konu-askeri"], yer_id:"", odak_kimlik:["aragon","kastilya"], devletler:["aragon","kastilya"], d:"Kastilya'daki taht kavgasında La Cerda prenslerini destekleyen II. Jaime, Biar geçidinden inerek Alicante, Elche ve Orihuela yöresini, ardından Murcia şehrini aldı. Bu işgal, 1304 Torrellas hakem kararıyla kısmen kalıcılaştı: kuzey kesim Valensiya Krallığı'na katıldı.", kaynak:"Gran Enciclopèdia Catalana, `jaume-ii-de-catalunya-arago`, `alacant`" },
{ t:"1299-01-01", gun:"yalnız yıl (TDV `nasriler`: 1299)", b:"II. Muhammed, Kastilya'ya karşı Aragon ile ittifak kurdu", tur:"ittifak", onem:2, dunya:1, kapsam:"dis", etiket:["ittifak","aragon","konu-siyasi"], yer_id:"Granada", devletler:["granada","aragon"], d:"Saltanatının son yıllarında II. Muhammed, Kastilya baskısını dengelemek için Aragon Krallığı ile ittifak yaptı. Bu adım, Nasrîlerin iki Hristiyan krallığı birbirine karşı kullanma siyasetinin erken örneğidir.", kaynak:"TDV `nasriler`" },
{ t:"1302-01-01", gun:"yalnız yıl: 701 (1302) — TDV hükümdar listesi; 701 H. Eylül 1301–Ağustos 1302'yi kapsar, gün yok", b:"II. Muhammed öldü, III. Muhammed el-Mahlû tahta geçti", tur:"hukumdar", onem:2, dunya:1, kapsam:"ic", etiket:["hukumdar","nasri-sultanlari","konu-siyasi"], yer_id:"Granada", devlet:"granada", d:"II. Muhammed'in ölümüyle oğlu III. Muhammed Nasrî tahtına çıktı. Kısa saltanatı Merînîlerle ilişkilerin bozulması ve Elhamra'daki Saray Mescidi gibi yapılarla anılır.", kaynak:"TDV `nasriler` (hükümdar listesi) · TDV `elhamra-sarayi`" },
{ t:"1304-08-08", gun:"8 Ağustos 1304 (Torrellas hakem kararı; RAH). Tamamlayıcı Elche antlaşması 19 Mayıs 1305", b:"Torrellas hakem kararı — Murcia sınırı ve la Cerda meselesi çözüldü", tur:"antlasma", onem:4, dunya:1, kapsam:"dis", etiket:["antlasma","murcia-siniri","konu-siyasi"], yer_id:"", odak_kimlik:["kastilya","aragon"], devletler:["kastilya","aragon"], d:"Portekiz kralı Dinis, infante Juan ve Zaragoza piskoposundan oluşan hakem heyeti, IV. Fernando ile II. Jaime arasındaki Murcia anlaşmazlığını Torrellas'ta karara bağladı; Alfonso de la Cerda'ya tazminat karşılığı taht iddiası askıya alındı. 19 Mayıs 1305 Elche antlaşması Murcia sınırını kesinleştirdi ve Alicante-Orihuela kesimini Aragon'a bıraktı; böylece Kastilya iç savaşı ve Aragon savaşı kapandı.", kaynak:"C. González Mínguez, \"Fernando IV\", RAH DB~e (biografias/16456)" },
{ t:"1306-01-01", gun:"yalnız yıl: 705/1306 (TDV `nasriler`)", b:"Nasrîler Merînîlere ait Sebte'yi ele geçirdi", tur:"toprak-kazanc", onem:3, dunya:1, kapsam:"dis", etiket:["toprak-kazanc","sebte","konu-askeri"], yer_id:"Sebte (Ceuta)", devletler:["granada","merini"], d:"III. Muhammed döneminde Merînîlerle ilişkiler koptu ve Nasrîler Boğaz'ın Afrika yakasındaki Sebte'yi (Ceuta) aldı. Şehir birkaç yıl sonra Merînîlerce geri alındı; olay iki müttefik hanedan arasındaki güvensizliği gösterir.", kaynak:"TDV `nasriler`" },
{ t:"1309-01-01", gun:"yalnız yıl (TDV 709/1309; GEC 'estiu del 1309')", b:"Meriye (Almería) kuşatması sonuçsuz kaldı", tur:"savas", onem:2, dunya:1, kapsam:"dis", etiket:["savas","nasri-iliskileri","konu-askeri"], yer_id:"Almería", devletler:["aragon","granada"], d:"Kastilya ile Gırnata'yı paylaşma anlaşması uyarınca II. Jaime, kendisine düşen pay olan Meriye'yi karadan ve denizden kuşattı. Kastilya'nın Cezîretülhadrâ cephesinde beklenen desteği gelmeyince kuşatma başarısız oldu ve Aragon ordusu kötü şartlarda çekildi. Aragon'un Endülüs'te toprak kazanma girişimlerinin sonuncusu oldu.", kaynak:"TDV `meriye` — '709 (1309) yılında Aragon Kralı … şehri işgal teşebbüsü sonuçsuz kaldı'; Gran Enciclopèdia Catalana `jaume-ii-de-catalunya-arago`" },
{ t:"1309-01-01", gun:"yalnız yıl: 708/1309 (TDV `nasriler`); gün yok", b:"III. Muhammed tahttan indirildi, kardeşi Nasr (Ebü'l-Cüyûş) sultan oldu", tur:"hukumdar", onem:3, dunya:1, kapsam:"ic", etiket:["hukumdar","nasri-sultanlari","konu-siyasi"], yer_id:"Granada", devlet:"granada", d:"Saltanatının beşinci yılında III. Muhammed, kardeşi Ebü'l-Cüyûş Nasr tarafından tahttan indirildi. Yeni sultanın döneminde Sebte Merînîlere geri döndü ve Cebelitârık Kastilya'ya kaptırıldı.", kaynak:"TDV `nasriler`" },
{ t:"1309-09-12", gun:"12 Eylül 1309 (RAH). TDV `cebelitarik` 709 (1309) der; TDV `nasriler` aynı olayı 709/1310 diye verir — 709 H. = Haziran 1309–Mayıs 1310, çelişki çevirim kaynaklı", b:"Kastilya Cebelitârık'ı aldı", tur:"toprak-kazanc", onem:3, dunya:2, kapsam:"dis", etiket:["toprak-kazanc","bogaz-savasi","konu-askeri"], yer_id:"Cebelitarık (Gibraltar)", devletler:["kastilya","granada"], d:"Aragon ile yapılan Alcalá de Henares anlaşması uyarınca Kastilya Cezîretülhadrâ'yı, Aragon Meriye'yi kuşattı. Cezîretülhadrâ kuşatması soyluların ayrılmasıyla dağıldı; seferin tek kalıcı kazancı, Alonso Pérez de Guzmán'ın IV. Fernando adına Cebelitârık'ı alması oldu. Gırnata emîri bunun üzerine Merînîleri yardıma çağırdı; şehir 1333'te müslümanlara geri döndü.", kaynak:"TDV `cebelitarik` ('709 (1309) yılında Alonso Pérez de Guzmán ... IV. Ferdinand adına Cebelitârık'ı istilâ etti'); C. González Mínguez, \"Fernando IV\", RAH DB~e 16456 (gün)" },
{ t:"1312-09-07", gun:"7 Eylül 1312 (RAH)", b:"IV. Fernando Jaén'de öldü — bir yaşındaki XI. Alfonso tahta geçti", tur:"hukumdar", onem:3, dunya:1, kapsam:"ic", etiket:["hukumdar","kastilya-taht","konu-siyasi"], yer_id:"", odak_kimlik:["kastilya"], devlet:"kastilya", d:"Gırnata'ya karşı sefer sürerken IV. Fernando Jaén'de ansızın öldü. Tahta bir yaşındaki oğlu XI. Alfonso çıktı; 1325'e dek süren vesayet dönemleri soylu kliklerin iktidar kavgasına sahne oldu.", kaynak:"C. González Mínguez, \"Fernando IV\", RAH DB~e 16456; J. Valdeón Baruque, \"Alfonso XI\", RAH DB~e 1020" },
{ t:"1314-01-01", gun:"yalnız yıl: 713/1314 (TDV `nasriler`); gün yok", b:"Nasr'ın Kastilya'ya vergi tavizi üzerine ayaklanma: I. İsmâil tahta çıktı", tur:"hukumdar", onem:3, dunya:1, kapsam:"ic", etiket:["hukumdar","nasri-sultanlari","konu-siyasi"], yer_id:"Granada", devlet:"granada", d:"Nasr, Merînîlerin Endülüs'e geçişini önlemek için Kastilya ile anlaşmış, fakat saldırıları durduramayınca vergi ödemeyi kabul etmişti. Bu taviz isyana yol açtı ve I. İsmâil tahtı ele geçirdi; on iki yıllık saltanatında iç istikrarı yeniden sağladı.", kaynak:"TDV `nasriler`" },
{ t:"1318-01-01", gun:"yalnız yıl: TDV `nasriler` 1318 diyor; gün yok. (Başka literatürde farklı yıl geçebilir — doğrulanmadı)", b:"I. İsmâil Gırnata'ya saldıran Kastilya ordusunu ağır yenilgiye uğrattı", tur:"savas", onem:3, dunya:1, kapsam:"dis", etiket:["savas","gırnata-savunmasi","konu-askeri"], yer_id:"Granada", devletler:["granada","kastilya"], d:"Gırnata üzerine yürüyen Kastilya kuvvetleri I. İsmâil karşısında ağır bir bozguna uğradı. Nasrîler bu zaferin ardından Kastilya'nın elindeki bazı merkezleri geri aldı.", kaynak:"TDV `nasriler`" },
{ t:"1321-01-01", gun:"yalnız yıl (TDV `nasriler`: 1321)", b:"Aragon ile beş yıllık ticaret ve askerî yardım antlaşması", tur:"antlasma", onem:2, dunya:1, kapsam:"dis", etiket:["antlasma","aragon","konu-ekonomi"], yer_id:"Granada", devletler:["granada","aragon"], d:"I. İsmâil, Aragon kralıyla beş yıl geçerli bir antlaşma imzaladı. Antlaşma deniz ve kara ticaretini serbest bırakıyor, limanları karşılıklı açıyor, askerî yardımlaşmayı ve Aragon'daki Müslümanlardan dileyenlerin Gırnata'ya göçünü öngörüyordu.", kaynak:"TDV `nasriler`" },
{ t:"1323-06-14", gun:"14 Haziran 1323 (GEC 'conquesta de Sardenya'); ⚠️ GEC'in 'Alfons III' maddesi 24 Haziran, bazı yayınlar 13 Haziran der — kaynak içi çelişki; filo 31 Mayıs'ta Portfangós'tan çıktı", b:"Veliaht Alfonso Sardinya'ya çıktı — ada fethi başladı", tur:"savas", onem:5, dunya:2, kapsam:"dis", etiket:["savas","sardinya-fethi","konu-askeri"], yer_id:"", odak_kimlik:["aragon","piza"], devletler:["aragon","piza"], d:"1297'de Papa'dan 'Sardinya ve Korsika krallığı' beratını alan II. Jaime, Arborea yargıcı II. Hugo ile ittifak kurduktan sonra oğlu veliaht Alfonso'yu yaklaşık üç yüz gemilik bir donanmayla gönderdi. Kuvvetler adanın güneybatısında Palmas körfezine (Palma di Sulcis) çıktı; Arborea yargıcı ve Sardinyalı beylerin çoğu burada Alfonso'ya bağlılık yemini etti. Direnen Pisa hâkimiyetindeki Villa di Chiesa ile Cagliari oldu.", kaynak:"Gran Enciclopèdia Catalana, `conquesta-de-sardenya`; `alfons-iii-de-catalunya`" },
{ t:"1323-07-04", gun:"Temmuz 1323 (Soddu); 4 Temmuz 1323 tarihli Sassari belgeleri (Tola, Codex diplomaticus Sardiniae, doc. XX ve Fragmenta XLV) Soddu'nun dipnot 28'inde — cümlenin kendisi görülemedi, gün ORTA güvenle", b:"Sassari Aragon tacına bağlılık sundu", tur:"toprak-kazanc", onem:4, dunya:1, kapsam:"dis", etiket:["toprak-kazanc","sardinya-fethi","konu-siyasi"], yer_id:"Sasari (Sassari)", devletler:["aragon","cenova"], d:"Cenova ile konfedere özerk bir komün olan Sassari, fethin başında kendiliğinden Aragon kralına bağlılık sundu ve imtiyazları tanındı. Temmuz 1323'te Sassari elçileri, Doria ve Malaspina beyleriyle birlikte Villa di Chiesa kuşatmasındaki veliaht Alfonso'ya biat etti. Ancak kötü yönetim ve Ceneviz kışkırtmasıyla şehir 1325'te ayaklanacaktı.", kaynak:"Alessandro Soddu, 'Corona d'Aragona e Malaspina nella Sardegna del Trecento' (dipnot 28, 30: P. Tola, Codex diplomaticus Sardiniae I, doc. XX, 1323 luglio 4); Gran Enciclopèdia Catalana `sasser-0` (yıl 1323)" },
{ t:"1324-01-01", gun:"yalnız yıl: 724 (1324) — TDV, İbnü'l-Hatîb'e dayanarak; gün yok", b:"Eşkür (Huéscar) kuşatmasında top kullanıldı", tur:"bilim", onem:2, dunya:2, kapsam:"dis", etiket:["bilim","barut-topu","konu-askeri"], yer_id:"Granada", devletler:["granada","kastilya"], d:"Lisânüddin İbnü'l-Hatîb'in kaydına göre Nasrîler Eşkür (Huéscar) Kalesi kuşatmasında top kullandı. TDV bunu Avrupa'da topun bilinen ilk kullanımları arasında sayar.", kaynak:"TDV `nasriler` (İbnü'l-Hatîb, el-İhâta I, 390 ve el-Lemhatü'l-bedriyye s. 85'e atıfla)" },
{ t:"1324-02-07", gun:"7 Şubat 1324 (GEC iki maddede aynı)", b:"Villa di Chiesa (Iglesias) teslim oldu", tur:"fetih", onem:4, dunya:1, kapsam:"dis", etiket:["fetih","sardinya-fethi","konu-askeri"], yer_id:"", odak_kimlik:["aragon","piza"], devletler:["aragon","piza"], d:"Pisa'nın madenci şehri Villa di Chiesa, 1 Temmuz 1323'te resmen başlayan ve açlık ile salgının iki tarafı da yıprattığı yedi aylık kuşatmadan sonra teslim oldu. Böylece Güneybatı Sardinya'nın gümüş madenleri Aragon'un eline geçti ve veliaht Alfonso ordusunu Cagliari'ye çevirdi.", kaynak:"Gran Enciclopèdia Catalana, `conquesta-de-sardenya`, `alfons-iii-de-catalunya`" },
{ t:"1324-02-29", gun:"29 Şubat 1324 (GEC 'batalla de Lucocisterna' ve 'Alfons III'); ⚠️ GEC 'conquesta de Sardenya' 1 Mart der", b:"Lucocisterna Muharebesi — Pisa ordusu yenildi", tur:"savas", onem:4, dunya:1, kapsam:"dis", etiket:["savas","sardinya-fethi","konu-askeri"], yer_id:"", odak_kimlik:["aragon","piza"], devletler:["aragon","piza"], d:"Cagliari'yi kurtarmak için Manfredo della Gherardesca komutasında gelen Pisa ordusu, şehrin yakınındaki Lucocisterna'da veliaht Alfonso'nun sayıca az kuvvetlerine yenildi. Aynı gün amiral Carròs da Pisa donanmasını liman önünde bozdu. Fethin tek meydan muharebesi olan bu zafer, Pisa'yı barış istemeye mecbur etti.", kaynak:"Gran Enciclopèdia Catalana, `batalla-de-lucocisterna`, `alfons-iii-de-catalunya`, `conquesta-de-sardenya`" },
{ t:"1324-06-19", gun:"19 Haziran 1324 (GEC)", b:"Cagliari kalesi teslim oldu — Pisa ile ilk barış", tur:"antlasma", onem:5, dunya:2, kapsam:"dis", etiket:["antlasma","sardinya-fethi","konu-siyasi"], yer_id:"Kalyari (Cagliari)", devletler:["aragon","piza"], d:"Kuşatma altındaki Cagliari kalesi teslim oldu ve Pisa ile barış (fiilen bir mütareke) imzalandı. Pisa, Sardinya'daki bütün öteki topraklarını Aragon'a bıraktı; yalnız Castello di Cagliari ile Gippi ve Trexenta bölgelerini Aragon kralının tımarı (vassal) olarak elinde tuttu. Karşısında Aragonlular Bonaria tepesinde kendi karargâh kasabalarını kurdu. Fetih böylece tamamlanmış sayıldı; veliaht Temmuz sonunda Katalonya'ya döndü.", kaynak:"Gran Enciclopèdia Catalana, `conquesta-de-sardenya`; `alfons-iii-de-catalunya`" },
{ t:"1325-01-01", gun:"yalnız yıl: 725 (1325) (TDV `nasriler`); gün yok", b:"I. İsmâil suikastla öldürüldü, oğlu IV. Muhammed tahta çıktı", tur:"hukumdar", onem:3, dunya:1, kapsam:"ic", etiket:["hukumdar","nasri-sultanlari","konu-siyasi"], yer_id:"Granada", devlet:"granada", d:"I. İsmâil bir suikast sonucu öldürüldü ve yerine oğlu IV. Muhammed geçti. Yeni sultan kısa süre sonra Kastilya'nın haçlı seferiyle kale kaybına uğradı ve amcasının ayaklanmasıyla uğraştı.", kaynak:"TDV `nasriler`" },
{ t:"1325-07-21", gun:"21 Temmuz 1325 (GEC)", b:"Sassari ayaklandı ve bağımsızlık ilân etti", tur:"isyan", onem:3, dunya:1, kapsam:"dis", etiket:["isyan","sardinya-fethi","konu-siyasi"], yer_id:"Sasari (Sassari)", devletler:["aragon","cenova"], d:"Cenova, Doria ve Malaspina ailelerinin kışkırtmasıyla ve kraliyet görevlilerinin baskıcı yönetimine tepkiyle Sassari halkı kral temsilcisini öldürüp bağımsızlık ilân etti. Şehir birkaç ay Aragon'dan kopuk kaldı; Arborea yargıcının arabuluculuğuyla barış Haziran 1326'da (Soddu: 28 Haziran 1326, Bonaria) yeniden sağlandı.", kaynak:"Gran Enciclopèdia Catalana, `conquesta-de-sardenya`, `sasser-0`; Soddu (28 Haziran 1326 barışı)" },
{ t:"1326-06-09", gun:"9 Haziran 1326 (GEC)", b:"Pisa Cagliari'yi teslim edip Sardinya'dan tamamen çekildi", tur:"toprak-kazanc", onem:5, dunya:2, kapsam:"dis", etiket:["toprak-kazanc","sardinya-fethi","konu-siyasi"], yer_id:"Kalyari (Cagliari)", devletler:["aragon","piza"], d:"1324'ten beri tımar olarak Pisa'da kalan Cagliari kalesinde Katalanlarla Pisalılar arasında çatışmalar sürmüş, Pisa Cenova ile birleşip yeni bir donanma hazırlamıştı. Ceneviz-Pisa yardım filosunun Carròs'a yenilmesinden sonra Cagliari krala teslim edildi ve yeni barışla Pisa Sardinya üzerindeki bütün haklarından vazgeçti. Şehir Katalan ve Aragonlularla yeniden iskân edildi, 1327'de belediye imtiyazları aldı ve adanın kraliyet idaresinin merkezi oldu.", kaynak:"Gran Enciclopèdia Catalana, `conquesta-de-sardenya`" },
{ t:"1327-11-02", gun:"2 Kasım 1327 (II. Jaime'nin ölümü, GEC)", b:"II. Jaime'nin ölümü — IV. Alfonso tahta çıktı", tur:"hukumdar", onem:2, dunya:1, kapsam:"ic", etiket:["hukumdar","barselona-hanedani","konu-siyasi"], yer_id:"", odak_kimlik:["aragon"], devlet:"aragon", d:"Sardinya fethini başlatan II. Jaime Barselona'da öldü; yerine fethi bizzat yöneten oğlu IV. Alfonso ('Benigno') geçti ve Paskalya 1328'de Zaragoza'da taç giydi. Saltanatı Sardinya'da Cenova destekli isyanlar ve sonuçsuz bir Gırnata haçlı seferi planıyla geçti; 1329'da yeniden ayaklanan Sassari yağmalanıp Katalan ve Aragonlularla iskân edildi.", kaynak:"Gran Enciclopèdia Catalana, `jaume-ii-de-catalunya-arago`, `alfons-iii-de-catalunya`, `sasser-0`" },
{ t:"1328-05-01", gun:"1 Mayıs 1328 Pamplona Curia General'i (RAH); öncesinde Puente la Reina meclisi 13-15 Mart 1328; taç giyme 5 Mart 1329 Pamplona", b:"Navarra Fransa'dan ayrıldı — II. Juana ve Évreux hanedanı tahta çağrıldı", tur:"hanedan", onem:5, dunya:1, kapsam:"dis", etiket:["hanedan","navarra-evreux","konu-siyasi"], yer_id:"Pamplona", devletler:["navarra","fransa"], d:"IV. Charles'ın 1328'de erkek vârissiz ölmesi üzerine Navarra meclisleri Fransız memurlarını görevden aldı ve Pamplona'daki genel toplantıda X. Louis'nin kızı Juana'yı ve eşi Évreuxlü Philippe'i meşru hükümdar olarak tanıdı. Böylece 44 yıllık Fransa-Navarra birliği sona erdi; Juana ile Philippe 5 Mart 1329'da Pamplona katedralinde geleneksel kalkan üzerine kaldırılma töreniyle taç giydiler.", kaynak:"R. Ciganda Elizondo, \"Juana II de Navarra\", RAH DB~e (biografias/24947)" },
{ t:"1333-01-01", gun:"yalnız yıl: 733 (1333) (TDV `nasriler`, `ebul-hasan-el-merini`); gün yok", b:"IV. Muhammed suikastla öldürüldü, I. Yûsuf tahta geçti", tur:"hukumdar", onem:3, dunya:1, kapsam:"ic", etiket:["hukumdar","nasri-sultanlari","konu-siyasi"], yer_id:"Granada", devlet:"granada", d:"Cebelitârık'ın Merînî yardımıyla geri alındığı yıl IV. Muhammed bir suikastla öldürüldü. On altı yaşındaki kardeşi Ebü'l-Haccâc I. Yûsuf tahta çıktı; yirmi bir yıllık saltanatı Hristiyan krallıklarla savaş ve Elhamra'nın büyük inşa evresiyle geçti.", kaynak:"TDV `nasriler` · TDV `ebul-hasan-el-merini`" },
{ t:"1336-01-24", gun:"24 Ocak 1336 (IV. Alfonso'nun ölümü, GEC)", b:"IV. Alfonso'nun ölümü — IV. Pedro 'Törenci' tahta çıktı", tur:"hukumdar", onem:3, dunya:1, kapsam:"ic", etiket:["hukumdar","barselona-hanedani","konu-siyasi"], yer_id:"", odak_kimlik:["aragon"], devlet:"aragon", d:"IV. Alfonso Barselona'da öldü ve yerine oğlu IV. Pedro geçti. Elli bir yıl süren saltanatı boyunca Mayorka'yı tekrar taca bağlayacak, soyluların Birlik isyanlarını ezecek, Cenova ve Kastilya ile uzun savaşlar yürütecekti. Saray ve kançılaryayı ayrıntılı nizamnamelerle düzenlediği için 'Törenci' (el Ceremonioso) diye anıldı.", kaynak:"Gran Enciclopèdia Catalana, `alfons-iii-de-catalunya`, `pere-iii-de-catalunya-arago`" },
{ t:"1343-05-25", gun:"25 Mayıs 1343 Santa Ponça çıkarması (GEC 'Jaume III de Mallorca'); Palma'ya giriş günü kaynakta yok", b:"IV. Pedro Mayorka'ya çıktı — Mayorka Krallığı taca bağlandı", tur:"toprak-kazanc", onem:4, dunya:1, kapsam:"dis", etiket:["toprak-kazanc","mayorka","konu-siyasi"], yer_id:"Mayorka (Palma)", devletler:["aragon","mayorka"], d:"IV. Pedro, vassalı ve eniştesi Mayorka kralı III. Jaime'yi açtığı bir davada suçlu ilân ettirip topraklarını müsadere ettirdi, ardından donanmasıyla Santa Ponça'ya çıktı. III. Jaime Rusiyon'a kaçtı, Mayorka, Menorka ve İbiza direnmeden teslim oldu. 1344'teki iki seferle Rusiyon ve Cerdanya da alındı; I. Jaime'nin 1276'daki bölünmesi böylece kapatıldı.", kaynak:"Gran Enciclopèdia Catalana, `jaume-iii-de-mallorca`, `pere-iii-de-catalunya-arago`" },
{ t:"1344-01-01", gun:"yalnız yıl: 744/1344 (TDV `nasriler`); gün yok", b:"Cezîretülhadrâ kaybedildi, I. Yûsuf Kastilya ve Aragon ile barışa mecbur kaldı", tur:"antlasma", onem:4, dunya:2, kapsam:"dis", etiket:["antlasma","cezireulhadra","konu-siyasi"], yer_id:"Granada", devletler:["granada","kastilya","aragon"], d:"Tarîf (Salado) yenilgisinin ardından Cezîretülhadrâ (Algeciras) da Kastilya'ya geçti ve Boğaz kıyısında yalnız Cebelitârık kaldı. I. Yûsuf 1344'te Kastilya ve Aragon ile barış yapmak zorunda kaldı. TDV'ye göre Kuzey Afrika yardımı bu noktada kesildi ve Nasrîler kalıcı olarak savunma siyasetine çekildi.", kaynak:"TDV `nasriler` · TDV `meriniler`" },
{ t:"1348-01-01", gun:"yalnız yıl: Adalet Kapısı kitabesi 749 (1348) tarihli (TDV); gün yok", b:"Elhamra'nın Adalet Kapısı inşa edildi", tur:"mimari", onem:2, dunya:2, kapsam:"ic", etiket:["mimari","elhamra","konu-kultur"], yer_id:"Granada", devlet:"granada", d:"I. Yûsuf döneminde Elhamra'nın sur ve kuleleri genişletildi; bu evrenin tarihli tanığı 749 (1348) kitabeli Adalet Kapısı'dır. Elhamra'nın bugün ayakta kalan bölümlerinin büyük kısmı I. Yûsuf ile oğlu V. Muhammed dönemine aittir.", kaynak:"TDV `elhamra-sarayi`" },
{ t:"1348-01-01", gun:"yalnız yıl (RAH gün vermiyor)", b:"Alcalá Cortes'i — Ordenamiento de Alcalá kanunnamesi", tur:"kanun", onem:4, dunya:2, kapsam:"ic", etiket:["kanun","hukuk-kodifikasyon","konu-idari"], yer_id:"", odak_kimlik:["kastilya"], devlet:"kastilya", d:"XI. Alfonso'nun Alcalá de Henares'te topladığı Cortes, Roma hukuku ilkelerine dayanan geniş bir kanunname kabul etti. Ordenamiento, kraliyet hukukunu yerel fuero'ların önüne koydu ve X. Alfonso'nun Siete Partidas'ını tamamlayıcı hukuk olarak yürürlüğe soktu; Kastilya hukukunun yüzyıllarca temel metinlerinden biri oldu.", kaynak:"J. Valdeón Baruque, \"Alfonso XI\", RAH DB~e (biografias/1020)" },
{ t:"1348-07-21", gun:"21 Temmuz 1348 (GEC)", b:"Épila Muharebesi — Aragon Birliği ezildi", tur:"isyan", onem:3, dunya:1, kapsam:"ic", etiket:["isyan","birlik-savasi","konu-siyasi"], yer_id:"", odak_kimlik:["aragon"], devlet:"aragon", d:"IV. Pedro'nun kızını veliaht ilân etmesine tepkiyle kardeşi Prens Fernando önderliğinde örgütlenen Aragon soylularının Birliği (Unión), kralı Zaragoza ve Valensiya'da imtiyaz vermeye zorlamıştı. Épila'da kralın Katalan ve Aragonlu kuvvetleri Birlik ordusunu yendi; kral Zaragoza'ya girip zorla verdiği imtiyazları iptal etti. Valensiya Birliği de kısa süre sonra Mislata'da yenildi.", kaynak:"Gran Enciclopèdia Catalana, `batalla-depila`, `pere-iii-de-catalunya-arago`" },
{ t:"1349-01-01", gun:"yalnız yıl: 750 (1349) (TDV `nasriler`, `gani-billah`); gün yok", b:"I. Yûsuf Gırnata'da Endülüs'ün ilk medresesini kurdurdu", tur:"kultur", onem:2, dunya:1, kapsam:"ic", etiket:["kultur","medrese","konu-kultur"], yer_id:"Granada", devlet:"granada", d:"I. Yûsuf'un Gırnata'da yaptırdığı medrese, Endülüs'teki ilk medrese kabul edilir; o zamana dek dinî ilimler camilerde okutuluyordu. Bu kurumu başkaları izledi ve derslere tıp, kimya, felsefe ve astronomi de eklendi.", kaynak:"TDV `nasriler` · TDV `gani-billah`" },
{ t:"1349-10-06", gun:"6 Ekim 1349 II. Juana'nın ölümü (RAH); II. Carlos Pamplona'da 27 Haziran 1350'de kral ilan edilip taç giydi", b:"II. Juana öldü, 'Kötü' II. Carlos Navarra kralı oldu", tur:"hukumdar", onem:4, dunya:1, kapsam:"ic", etiket:["hukumdar","navarra-evreux","konu-siyasi"], yer_id:"Pamplona", devlet:"navarra", d:"Kara Ölüm yıllarında II. Juana'nın ölümüyle Évreux kontu olarak Fransa'da büyümüş oğlu II. Carlos Navarra tahtına geçti; Pamplona'daki ilanına ilk kez kutsal yağla meshetme törenini ekletti. Saltanatı boyunca Normandiya'daki Fransız topraklarını ve Valois tahtına yakınlığını Navarra'nın küçük gücüyle birleştirerek Yüz Yıl Savaşları'nın hareketli oyuncularından biri oldu.", kaynak:"R. Ciganda Elizondo, \"Carlos II\", RAH DB~e (biografias/9668); \"Juana II de Navarra\", RAH DB~e 24947" },
{ t:"1349-10-25", gun:"25 Ekim 1349 (GEC)", b:"Llucmajor Muharebesi — son Mayorka kralı öldürüldü", tur:"savas", onem:3, dunya:1, kapsam:"dis", etiket:["savas","mayorka","konu-askeri"], yer_id:"Mayorka (Palma)", devletler:["aragon","mayorka"], d:"Montpellier'i Fransa kralına satarak paralı asker toplayan III. Jaime, tahtını geri almak için Mayorka'ya çıktı. Llucmajor yakınında IV. Pedro'nun valisi Gilabert de Centelles'e yenildi ve savaş alanında öldürüldü, oğlu esir düştü. Mayorka Krallığı'nın Aragon tacına kesin olarak bağlanması bu muharebeyle tamamlandı.", kaynak:"Gran Enciclopèdia Catalana, `batalla-de-llucmajor`" },
{ t:"1350-03-27", gun:"27 Mart 1350 (RAH künyesi ve metni). Metin 'Kutsal Cuma' der; bazı kaynaklar 26 Mart verir — bildirilir", b:"XI. Alfonso Cebelitârık kuşatmasında Kara Ölüm'den öldü", tur:"olum", onem:4, dunya:2, kapsam:"ic", etiket:["olum","kara-olum","konu-siyasi"], yer_id:"Cebelitarık (Gibraltar)", devlet:"kastilya", d:"İber yarımadasına da yayılan veba salgını, Cebelitârık'ı kuşatan XI. Alfonso'nun ordugâhını vurdu ve kral hastalığa yakalanarak öldü. Salgın Kastilya'da tarım toprakları boşaltıp koyunculuğu öne çıkaran derin bir nüfus ve ekonomi bunalımı başlattı. Tahta genç oğlu I. Pedro geçti.", kaynak:"J. Valdeón Baruque, \"Alfonso XI\", RAH DB~e (biografias/1020), Crónica de Alfonso XI'e atıfla" },
{ t:"1354-01-01", gun:"yalnız yıl 1354 (GEC 'Pere III' ve 'l'Alguer'); gün kaynakta yok", b:"Alghero ele geçirildi ve Katalanlarla iskân edildi", tur:"fetih", onem:3, dunya:1, kapsam:"dis", etiket:["fetih","sardinya","konu-askeri"], yer_id:"", odak_kimlik:["aragon","cenova"], devletler:["aragon","cenova"], d:"Doria ailesinin 1353'te Cenova'ya bıraktığı Alghero'yu, IV. Pedro bizzat başında bulunduğu yeni bir donanmayla kesin olarak ele geçirdi. Halkı çıkarılan şehir Katalanlarla yeniden iskân edildi; bugün de konuşulan Alghero Katalancası bu iskânın mirasıdır. Ancak Arborea yargıcı IV. Mariano'nun Cenova safına geçmesiyle adadaki savaş sürdü.", kaynak:"Gran Enciclopèdia Catalana, `pere-iii-de-catalunya-arago`, `lalguer-0`" },
{ t:"1354-10-19", gun:"Ramazan bayramı, 19 Ekim 1354 — TDV `gani-billah` tam gün", b:"I. Yûsuf bayram namazında öldürüldü, V. Muhammed tahta çıktı", tur:"hukumdar", onem:3, dunya:1, kapsam:"ic", etiket:["hukumdar","nasri-sultanlari","konu-siyasi"], yer_id:"Granada", devlet:"granada", d:"I. Yûsuf'un Ramazan bayramında öldürülmesi üzerine on beş yaşındaki oğlu V. Muhammed Ganî-Billâh lakabıyla tahta geçti. Birinci saltanatında Kastilya'ya haraç ödemeyi sürdürdü; veziri Rıdvân ve Dîvân-ı İnşâ başındaki Lisânüddin İbnü'l-Hatîb idareyi yürüttü.", kaynak:"TDV `gani-billah` · TDV `nasriler`" },
{ t:"1356-01-01", gun:"yalnız yıl (RAH); Castilya Tarazona'yı Mart 1357'de aldı", b:"İki Pedro Savaşı başladı — Kastilya ile Aragon karşı karşıya", tur:"savas", onem:3, dunya:1, kapsam:"dis", etiket:["savas","iki-pedro-savasi","konu-askeri"], yer_id:"", odak_kimlik:["kastilya","aragon"], devletler:["kastilya","aragon"], d:"Sanlúcar açıklarında Katalan korsanın Kastilya'nın müttefiki Cenova'yla bağlantılı gemilere el koyması, I. Pedro ile Aragonlu IV. Pedro arasındaki gerginliği savaşa çevirdi. Kastilya başta üstün geldi ve 1357'de Tarazona'yı aldı; Terrer (1361) barışı kısa bir ara verdi. Aragon'un Trastámaralı Enrique'yi desteklemesi, savaşı Kastilya iç savaşıyla birleştirdi.", kaynak:"J. Valdeón Baruque, \"Pedro I de Castilla\", RAH DB~e (biografias/35772)" },
{ t:"1359-01-01", gun:"yalnız yıl: 760 (1359) (TDV `nasriler`, `gani-billah`); gün yok", b:"Saray darbesi: V. Muhammed tahtını kaybetti, II. İsmâil sultan ilân edildi", tur:"hukumdar", onem:3, dunya:1, kapsam:"ic", etiket:["hukumdar","ic-savas","konu-siyasi"], yer_id:"Granada", devlet:"granada", d:"Hanedandan Muhammed b. İsmâil b. Ferec Elhamra'yı basıp Hâcib Rıdvân'ı öldürdü ve tutuklu II. İsmâil'i sultan ilân etti. Vâdîâş'a kaçan V. Muhammed, Kastilya'dan beklediği desteği bulamayınca Merînî Sultanı Ebû Sâlim'in davetiyle 1360'ta Fas'a sığındı. Ertesi yıl darbenin önderi II. İsmâil'i öldürüp VI. Muhammed olarak tahta geçti.", kaynak:"TDV `gani-billah` · TDV `nasriler`" },
{ t:"1362-04-16", gun:"20 Cemâziyelâhir 763 / 16 Nisan 1362 — TDV tam gün", b:"V. Muhammed Gırnata'ya dönüp ikinci kez tahta çıktı", tur:"hukumdar", onem:4, dunya:1, kapsam:"ic", etiket:["hukumdar","nasri-sultanlari","konu-siyasi"], yer_id:"Granada", devlet:"granada", d:"Fas'tan dönüp Runde'ye (Ronda) yerleşen V. Muhammed, Kastilya'nın da desteğiyle Mâleka ve çevresini aldı; VI. Muhammed 13 Nisan'da şehri terk edince 16 Nisan 1362'de yeniden tahta oturdu. Otuz yıla yakın ikinci saltanatı TDV'ye göre Nasrîlerin en parlak dönemidir.", kaynak:"TDV `gani-billah` · TDV `nasriler`" },
{ t:"1364-05-16", gun:"16 Mayıs 1364 (RAH)", b:"Cocherel yenilgisi — II. Carlos'un Fransa'daki gücü kırıldı", tur:"savas", onem:3, dunya:1, kapsam:"dis", etiket:["savas","yuz-yil-savaslari","konu-askeri"], yer_id:"Pamplona", devletler:["navarra","fransa"], d:"1356'da Rouen'de Fransa kralınca tutuklanıp sonra kaçan II. Carlos, Normandiya topraklarını korumak için İngilizlerle birlikte savaştı; Navarra-İngiliz ordusu Cocherel'de Du Guesclin'e yenildi ve Normandiya'daki mülklerin çoğu işgal edildi. Yenilgi, Navarra kralının Fransız tahtı siyasetindeki yükselişini bitirdi ve ilgisini Kastilya-Aragon cephesine çevirdi.", kaynak:"R. Ciganda Elizondo, \"Carlos II\", RAH DB~e (biografias/9668)" },
{ t:"1366-04-05", gun:"5 Nisan 1366, Paskalya günü (RAH; kronikten Latince alıntıyla)", b:"Trastámaralı Enrique Burgos'ta (Las Huelgas) Kastilya kralı olarak taç giydi", tur:"hukumdar", onem:4, dunya:2, kapsam:"ic", etiket:["hukumdar","kastilya-ic-savasi","konu-siyasi"], yer_id:"Burgos", devlet:"kastilya", d:"Fransa'nın gönderdiği Du Guesclin'in paralı Beyaz Kumpanyaları ve Aragon desteğiyle Mart 1366'da Calahorra'dan Kastilya'ya giren Enrique, I. Pedro'yu zorba ilan edip Las Huelgas manastırında taç giydi. I. Pedro Burgos, Toledo ve Sevilla'yı bırakıp Bayonne'a, İngilizlere sığındı; Kastilya iç savaşı Yüz Yıl Savaşları'nın bir cephesine dönüştü.", kaynak:"J. Valdeón Baruque, \"Enrique II\", RAH DB~e (biografias/15073); aynı yazar, \"Pedro I de Castilla\", RAH DB~e 35772" },
{ t:"1367-04-03", gun:"3 Nisan 1367 (RAH)", b:"Nájera Savaşı — Kara Prens'in desteğiyle I. Pedro tahtını geri aldı", tur:"savas", onem:4, dunya:2, kapsam:"dis", etiket:["savas","kastilya-ic-savasi","konu-askeri"], yer_id:"", odak_kimlik:["kastilya","ingiltere"], devletler:["kastilya","ingiltere"], d:"Libourne antlaşmasıyla Kara Prens'i yanına çeken I. Pedro, Navarra'dan geçen İngiliz-Gaskon ordusuyla Nájera'da Trastámara kuvvetlerini ağır bir yenilgiye uğrattı; Du Guesclin esir düştü, Enrique Fransa'ya kaçtı. Ancak Kara Prens aynı yaz ödenmeyen masraflar yüzünden çekilince zaferin getirisi kısa sürdü.", kaynak:"J. Valdeón Baruque, \"Pedro I de Castilla\" ve \"Enrique II\", RAH DB~e 35772 / 15073" },
{ t:"1369-01-01", gun:"Zilhicce 770 / Temmuz 1369 (TDV `gani-billah`); gün yok → YYYY-01-01", b:"Cezîretülhadrâ, Merînî donanması desteğiyle Kastilya'dan geri alındı", tur:"toprak-kazanc", onem:3, dunya:1, kapsam:"dis", etiket:["toprak-kazanc","cezireulhadra","konu-askeri"], yer_id:"Granada", devletler:["granada","merini","kastilya"], d:"Kastilya'da I. Pedro'nun öldürülmesiyle çıkan karışıklıktan yararlanan V. Muhammed, Merînî Sultanı I. Abdülazîz'in donanmasının desteğiyle çeyrek yüzyıldır Kastilya'da olan Cezîretülhadrâ'yı (Algeciras) geri aldı. Ardından Aragon ve Kastilya ile barışlar yapıldı.", kaynak:"TDV `gani-billah` · TDV `nasriler` · TDV `meriniler`" },
{ t:"1369-03-23", gun:"22/23 Mart 1369 gecesi (RAH; López de Ayala kroniği '23 Mart'). Montiel meydan savaşı 14 Mart 1369", b:"Montiel — I. Pedro öldürüldü, Trastámara hanedanı tahta yerleşti", tur:"hanedan", onem:5, dunya:2, kapsam:"ic", etiket:["hanedan","kastilya-ic-savasi","konu-siyasi"], yer_id:"", odak_kimlik:["kastilya"], devlet:"kastilya", d:"14 Mart'ta Montiel önünde yenilen I. Pedro kaleye sığındı; 22-23 Mart gecesi Du Guesclin'in çadırında üvey kardeşi Enrique ile yüz yüze gelince boğuşmada öldürüldü. Kastilya iç savaşı Trastámara zaferiyle bitti ve II. Enrique'nin hanedanı Kastilya'yı (sonra Aragon'u da) 1504'e dek yönetti.", kaynak:"J. Valdeón Baruque, \"Pedro I de Castilla\" ve \"Enrique II\", RAH DB~e 35772 / 15073" },
{ t:"1372-01-01", gun:"gün yok: RAH yalnız 1372; ikincil kaynaklar 22-23 ya da 23-24 Haziran der — ayrışıyor, yazılmadı", b:"La Rochelle deniz zaferi — Kastilya galeleri İngiliz filosunu yendi", tur:"savas", onem:3, dunya:2, kapsam:"dis", etiket:["savas","yuz-yil-savaslari","konu-askeri"], yer_id:"", odak_kimlik:["kastilya","ingiltere","fransa"], devletler:["kastilya","ingiltere","fransa"], d:"II. Enrique, tahtını borçlu olduğu Fransa'yla Kasım 1368 Toledo paktıyla kurduğu ittifak gereği Yüz Yıl Savaşları'na deniz gücüyle katıldı. Kastilya galeleri La Rochelle önünde Pembroke kontunun İngiliz filosunu dağıtıp kontu esir aldı; bu, Kastilya donanmasının Atlantik'teki ağırlığını gösteren ilk büyük zaferdi ve Fransa'nın Poitou'yu geri almasının önünü açtı.", kaynak:"J. Valdeón Baruque, \"Enrique II\", RAH DB~e (biografias/15073), López de Ayala kroniğine atıfla" },
{ t:"1374-01-01", gun:"yıl yaklaşık: TDV `gani-billah` Cebelitârık'ın alınmasını I. Abdülazîz'in ölümü (774/1373) ile Ahmed b. Ebû Sâlim'in tahta çıkışı (776/1374) arasına koyar; gün yok. ⚠️ TDV `cebelitarik` Nasrî hâkimiyetini '1410-1462' diye verir — tutarsızlık", b:"Cebelitârık Nasrîlere geçti, Endülüs'teki Merînî varlığı sona erdi", tur:"toprak-kazanc", onem:3, dunya:1, kapsam:"dis", etiket:["toprak-kazanc","cebelitarik","konu-siyasi"], yer_id:"Cebelitarık (Gibraltar)", devletler:["granada","merini"], d:"Merînî Sultanı I. Abdülazîz'in ölümünden sonra V. Muhammed, Merînîlerin Endülüs'teki son dayanağı Cebelitârık'ı aldı ve Fas'taki taht kavgasında Ahmed b. Ebû Sâlim'i destekledi. Daha önce Merînî komutanların yönettiği şeyhülguzâtlık kurumunu da kaldırmış olan sultan, böylece Endülüs'teki Merînî askerî varlığına son verdi.", kaynak:"TDV `gani-billah` · TDV `meriniler` · TDV `nasriler` (çelişen: TDV `cebelitarik`)" },
{ t:"1379-03-31", gun:"31 Mart 1379 (RAH, iki biyografide aynı)", b:"Briones Antlaşması — Navarra Kastilya himayesine girdi", tur:"antlasma", onem:4, dunya:1, kapsam:"dis", etiket:["antlasma","navarra-kastilya","konu-siyasi"], yer_id:"Pamplona", devletler:["navarra","kastilya"], d:"1378 yazında Kastilya ordusunun Pamplona'yı kuşatması ve Fransa'daki mülklerinin elden çıkmasıyla yalnız kalan II. Carlos, Briones'te ağır şartlı bir barış imzalamak zorunda kaldı; bir dizi Navarra kalesi Kastilya işgalinde kaldı. Antlaşma Navarra üzerinde fiilî bir Kastilya himayesi kurdu; şartları ancak 1383 El Espinar anlaşmasıyla yumuşatıldı.", kaynak:"R. Ciganda Elizondo, \"Carlos II\", RAH DB~e 9668; V. Á. Álvarez Palenzuela, \"Carlos III\", RAH DB~e 9671" },
{ t:"1379-05-29", gun:"29 Mayıs 1379 (RAH, I. Juan biyografisi); II. Enrique biyografisinin künyesi yalnız 'V.1379' der", b:"II. Enrique öldü, I. Juan Kastilya kralı oldu", tur:"hukumdar", onem:3, dunya:1, kapsam:"ic", etiket:["hukumdar","kastilya-taht","konu-siyasi"], yer_id:"", odak_kimlik:["kastilya"], devlet:"kastilya", d:"Trastámara hanedanının kurucusu II. Enrique, Navarra ile Santo Domingo de la Calzada barışını yaptığı yıl aynı kasabada öldü. Oğlu I. Juan tahta geçti ve geleneği aşarak 25 Temmuz'da Las Huelgas'ta kendini taç giydirdi.", kaynak:"L. Suárez Fernández, \"Juan I de Castilla\", RAH DB~e (biografias/24976); J. Valdeón Baruque, \"Enrique II\", RAH DB~e 15073" },
{ t:"1383-01-01", gun:"yalnız yıl (Segovia Cortes'i 1383; RAH)", b:"Segovia Cortes'i İspanyol Takvimi'ni kaldırıp Milâdî takvimi getirdi", tur:"reform", onem:2, dunya:1, kapsam:"ic", etiket:["reform","takvim","konu-kultur"], yer_id:"", odak_kimlik:["kastilya"], devlet:"kastilya", d:"I. Juan'ın 1383 Segovia Cortes'i, belgelerde yüzyıllardır kullanılan ve Milâttan 38 yıl önceden başlayan 'Era hispánica' yerine İsa'nın doğumundan sayılan takvimi resmîleştirdi. Aynı Cortes, Aragon'un saray teşkilatını örnek alan bir idari reform sürecinin de başlangıcıydı.", kaynak:"L. Suárez Fernández, \"Juan I de Castilla\", RAH DB~e (biografias/24976)" },
{ t:"1387-01-01", gun:"1 Ocak 1387 II. Carlos'un ölümü (RAH) — gerçek gün, yer tutucu değil", b:"II. Carlos öldü, 'Soylu' III. Carlos Navarra tahtına geçti", tur:"hukumdar", onem:3, dunya:1, kapsam:"ic", etiket:["hukumdar","navarra-evreux","konu-siyasi"], yer_id:"Pamplona", devlet:"navarra", d:"II. Carlos'un ölümüyle tahta geçen III. Carlos, babasının maceracı siyasetini bırakıp Kastilya ve Fransa ile barışa dayalı bir denge kurdu. Fransa'daki iddialarını 1404'te Nemours dükalığı karşılığında bıraktı, Cherbourg'u geri alıp sattı ve krallığın maliyesini düzeltti; saltanatı Navarra'nın geç Orta Çağ'daki en sakin dönemi sayılır.", kaynak:"V. Á. Álvarez Palenzuela, \"Carlos III\", RAH DB~e (biografias/9671); R. Ciganda Elizondo, \"Carlos II\", RAH DB~e 9668" },
{ t:"1387-01-05", gun:"5 Ocak 1387 (IV. Pedro'nun ölümü, GEC)", b:"IV. Pedro'nun ölümü — I. Juan tahta çıktı", tur:"hukumdar", onem:2, dunya:1, kapsam:"ic", etiket:["hukumdar","barselona-hanedani","konu-siyasi"], yer_id:"", odak_kimlik:["aragon"], devlet:"aragon", d:"Elli bir yıl hüküm süren IV. Pedro Barselona'da öldü ve yerine oğlu I. Juan geçti. Avcılık ve saray eğlencelerine düşkünlüğüyle 'Kayıtsız' lakabını alan Juan döneminde Sardinya'da Arborea isyanı sürdü ve taç ağır borç yükü altında kaldı.", kaynak:"Gran Enciclopèdia Catalana, `pere-iii-de-catalunya-arago`, `joan-i-de-catalunya-arago`" },
{ t:"1388-07-22", gun:"22 Temmuz 1388 (RAH, III. Enrique biyografisi); başka tarih veren kaynaklar olabilir, ikinci kaynakla sınanmadı", b:"Bayonne Antlaşması — Lancaster'ın taht iddiası evlilikle kapandı", tur:"antlasma", onem:4, dunya:2, kapsam:"dis", etiket:["antlasma","yuz-yil-savaslari","konu-siyasi"], yer_id:"", odak_kimlik:["kastilya","ingiltere"], devletler:["kastilya","ingiltere"], d:"I. Pedro'nun kızıyla evli olduğu için Kastilya tahtını talep eden Gantlı John (Lancaster dükü), 1386'da Galiçya'ya çıktığı halde halkı yanına çekemedi. Bayonne'da varılan anlaşmayla veliaht Enrique, Lancaster'ın kızı Catalina ile evlendi; dük yüklü bir tazminat karşılığı iddiasından vazgeçti. Böylece Trastámara hanedanının meşruiyeti üzerindeki tartışma kapandı.", kaynak:"M. T. Martialay Sacristán – F. Suárez Bilbao, \"Enrique III\", RAH DB~e (biografias/15076); L. Suárez Fernández, \"Juan I de Castilla\", RAH DB~e 24976" },
{ t:"1390-10-09", gun:"9 Ekim 1390 (RAH)", b:"I. Juan attan düşüp öldü — III. Enrique'nin vesayet dönemi başladı", tur:"hukumdar", onem:3, dunya:1, kapsam:"ic", etiket:["hukumdar","kastilya-taht","konu-siyasi"], yer_id:"", odak_kimlik:["kastilya"], devlet:"kastilya", d:"I. Juan, Alcalá de Henares'te atının tökezlemesiyle yere düşerek anında öldü. On bir yaşındaki III. Enrique için Ocak 1391 Madrid Cortes'i bir vesayet konseyi kurdu; hazine boştu, Portekiz'le ateşkes kırılgandı ve aynı yıl Yahudi katliamları patlak verdi.", kaynak:"L. Suárez Fernández, \"Juan I de Castilla\", RAH DB~e 24976; M. T. Martialay – F. Suárez Bilbao, \"Enrique III\", RAH DB~e 15076" },
{ t:"1391-01-17", gun:"10 Safer 793 / 17 Ocak 1391 — TDV `gani-billah` tam gün", b:"V. Muhammed öldü, oğlu II. Yûsuf tahta geçti", tur:"hukumdar", onem:3, dunya:1, kapsam:"ic", etiket:["hukumdar","nasri-sultanlari","konu-siyasi"], yer_id:"Granada", devlet:"granada", d:"Nasrîlerin en uzun ve en parlak saltanatlarından birini süren V. Muhammed 17 Ocak 1391'de öldü; yerine büyük oğlu II. Yûsuf geçti. TDV, onun ölümüyle Gırnata'nın ihtişam devrinin kapandığını ve zayıflama döneminin başladığını belirtir.", kaynak:"TDV `gani-billah` · TDV `nasriler`" },
{ t:"1396-05-19", gun:"19 Mayıs 1396 (I. Juan'ın ölümü, GEC)", b:"I. Juan'ın ölümü — I. Martin tahta çıktı", tur:"hukumdar", onem:2, dunya:1, kapsam:"ic", etiket:["hukumdar","barselona-hanedani","konu-siyasi"], yer_id:"", odak_kimlik:["aragon"], devlet:"aragon", d:"I. Juan av sırasında ani ölünce, erkek varis bırakmadığından taç kardeşi Martin'e geçti. Martin o sırada oğlunu Sicilya tahtında tutmak için adadaydı; dönüşüne kadar naipliği eşi Maria de Luna yürüttü ve Foix kontunun taht iddiasıyla giriştiği istilayı karşıladı.", kaynak:"Gran Enciclopèdia Catalana, `joan-i-de-catalunya-arago`, `marti-i-de-catalunya-arago`" },
{ t:"1402-01-01", gun:"yalnız yıl (1402, La Rochelle'den hareket; Lobo Cabrera). Britannica 1 Mayıs 1402 der ama sayfa 403 verdi, doğrulanamadı", b:"Béthencourt seferi — Kanarya Adaları'nın fethi başladı", tur:"toprak-kazanc", onem:3, dunya:3, kapsam:"dis", etiket:["toprak-kazanc","atlantik-genislemesi","konu-siyasi"], yer_id:"", odak_kimlik:["kastilya"], devlet:"kastilya", d:"Normandiyalı şövalye Jean de Béthencourt, Gadifer de La Salle ile birlikte Kanarya Adaları'nı fethetmek üzere La Rochelle'de sefer hazırlığına girişti ve aynı yıl takımadaya ulaştı. Senyörlük esasıyla yürütülen fetih, adaların Kastilya tacının hükümranlığı altına girmesinin başlangıcı sayılır; Kastilya'nın Kanaryalar üzerindeki hakkı 1479 Alcáçovas antlaşmasında Portekiz'e de kabul ettirildi.", kaynak:"M. Lobo Cabrera (Universidad de Las Palmas de Gran Canaria), \"El caballero normando Juan de Bethencourt\", Archivo Histórico Municipal de Teguise; J. L. Ferreira, \"Treaty of Alcáçovas-Toledo\", Enciclopédia Virtual da Expansão Portuguesa (FCSH-UNL)" },
{ t:"1403-05-22", gun:"22 Mayıs 1403 El Puerto de Santa María'dan denize açılış (Markham; Casa Asia). Elçiler 21 Mayıs Pazartesi limana varmıştı", b:"Clavijo elçiliği — III. Enrique'nin heyeti Semerkant'a, Timur'a yola çıktı", tur:"diplomasi", onem:3, dunya:3, kapsam:"dis", etiket:["diplomasi","timur-elciligi","konu-siyasi"], yer_id:"", odak_kimlik:["kastilya","timurlu"], devletler:["kastilya","timurlu"], d:"Ankara Savaşı'ndan sonra Timur'un gönderdiği elçiye karşılık III. Enrique, saray görevlisi Ruy González de Clavijo başkanlığında bir heyeti Semerkant'a yolladı; amaç Osmanlılara karşı bir yakınlaşma kurmaktı. Heyet Rodos, İstanbul ve Trabzon üzerinden Semerkant'a ulaştı; Clavijo'nun seyahatnamesi Timur sarayını ve Anadolu-İran yollarını anlatan en değerli Avrupa tanıklıklarındandır. Timur'un kısa süre sonra ölümü ilişkiyi sürdürmeyi olanaksız kıldı.", kaynak:"C. R. Markham (çev.), Narrative of the Embassy of Ruy Gonzalez de Clavijo to the Court of Timour at Samarcand, A.D. 1403-6, Hakluyt Society, London 1859 (giriş); Casa Asia Mediateca, \"Ruy González de Clavijo\" biyografi föyü" },
{ t:"1406-12-25", gun:"25 Aralık 1406 (RAH)", b:"III. Enrique öldü — iki yaşındaki II. Juan'ın uzun vesayeti başladı", tur:"hukumdar", onem:3, dunya:1, kapsam:"ic", etiket:["hukumdar","kastilya-taht","konu-siyasi"], yer_id:"", odak_kimlik:["kastilya"], devlet:"kastilya", d:"Hastalıklı yapısı yüzünden 'el Doliente' denen III. Enrique Toledo'da genç yaşta öldü. Vasiyetiyle yönetim, kraliçe Catalina ile kralın kardeşi Fernando'ya (sonraki Antequeralı Fernando) ortaklaşa bırakıldı; bu ikili naiplik, Aragon'un 'infante'lerinin Kastilya siyasetine yarım yüzyıl hâkim olmasının kapısını açtı.", kaynak:"V. Álvarez Palenzuela, \"Juan II de Castilla\", RAH DB~e (biografias/25005); \"Enrique III\", RAH DB~e 15076" },
{ t:"1409-06-26", gun:"26 Haziran 1409 (GEC 'batalla de Sanluri'); ⚠️ yaygın literatür 30 Haziran der — kaynaklar ayrışıyor", b:"Sanluri Muharebesi — Arborea direnişi kırıldı", tur:"savas", onem:4, dunya:1, kapsam:"dis", etiket:["savas","sardinya","konu-askeri"], yer_id:"", odak_kimlik:["aragon"], devletler:["aragon","arborea"], d:"Sicilya kralı genç Martin (Aragon tahtının varisi) komutasındaki Katalan ordusu, Cagliari yakınında Sanluri'de Arborea yargıçlığının ve müttefiki Narbonne vikontu II. Guillaume'un sayıca üstün ordusunu ağır yenilgiye uğrattı. Yarım asırdır adanın büyük kısmını elinde tutan Arborea'nın gücü kırıldı. Ancak galip Martin birkaç hafta sonra adada hastalanıp öldü ve Barselona hanedanı erkek varissiz kaldı.", kaynak:"Gran Enciclopèdia Catalana, `batalla-de-sanluri`" },
{ t:"1410-01-01", gun:"gün yok: RAH 'Eylül 1410'da teslim oldu' der; TDV yalnız 1410", b:"Naip Fernando Entekīre'yi (Antequera) aldı", tur:"toprak-kazanc", onem:3, dunya:1, kapsam:"dis", etiket:["toprak-kazanc","girnata-siniri","konu-askeri"], yer_id:"", odak_kimlik:["kastilya","granada"], devletler:["kastilya","granada"], d:"Gırnata'yla ateşkesin bitmesi üzerine naip Fernando, emirliğin iç yollarını denetleyen Entekīre'yi kuşattı; beklenenden uzun süren kuşatmanın sonunda şehir Eylül'de teslim oldu. Zafer Fernando'ya 'Antequeralı' lakabını ve iki yıl sonra Aragon tahtına giden yolda büyük prestij kazandırdı; şehirden göçen müslümanlar Gırnata'da aynı adı taşıyan bir mahalle kurdu.", kaynak:"TDV `girnata` ('1410'da Entekīre'den (Antequera) göçenler ... yeni bir mahalle kurdular'); V. Álvarez Palenzuela, \"Juan II de Castilla\", RAH DB~e 25005" },
{ t:"1410-05-31", gun:"31 Mayıs 1410 (GEC)", b:"I. Martin varissiz öldü — Barselona hanedanı sona erdi, fetret başladı", tur:"hanedan", onem:4, dunya:1, kapsam:"ic", etiket:["hanedan","fetret-1410","konu-siyasi"], yer_id:"Barselona", devlet:"aragon", d:"Oğlunu bir yıl önce kaybeden I. Martin halef belirlemeden Barselona'da öldü; ölüm döşeğinde yalnız tahtın 'hakkı olana' geçmesini onayladı. Beş yüzyıllık Barselona kontları hanedanının erkek soyu böylece kesildi. Urgell kontu Jaime, Anjou'lu Louis ve Kastilyalı Fernando gibi adaylar arasında iki yıl süren fetret dönemi başladı ve Caspe Uzlaşması'yla (1412) sonuçlandı.", kaynak:"Gran Enciclopèdia Catalana, `marti-i-de-catalunya-arago`, `compromis-de-casp`" },
{ t:"1416-04-02", gun:"2 Nisan 1416 (I. Fernando'nun ölümü, GEC)", b:"I. Fernando'nun ölümü — V. Alfonso tahta çıktı", tur:"hukumdar", onem:3, dunya:1, kapsam:"ic", etiket:["hukumdar","trastamara-hanedani","konu-siyasi"], yer_id:"", odak_kimlik:["aragon"], devlet:"aragon", d:"Caspe'de seçilen Trastámara hanedanının ilk kralı I. Fernando Igualada'da öldü; yerine oğlu V. Alfonso ('Cömert') geçti. Alfonso 1420'de Sardinya'daki son muhalefeti Narbonne vikontunun haklarını satın alarak tasfiye etti, ardından Napoli tahtına yöneldi ve hayatının son çeyrek asrını İtalya'da geçirdi.", kaynak:"Gran Enciclopèdia Catalana, `ferran-i-de-catalunya-arago`, `alfons-iv-de-catalunya`" },
{ t:"1420-07-14", gun:"14 Temmuz 1420 (RAH)", b:"Tordesillas darbesi — infante Enrique genç kral II. Juan'ı ele geçirdi", tur:"siyaset", onem:3, dunya:1, kapsam:"ic", etiket:["siyaset","aragon-infanteleri","konu-siyasi"], yer_id:"", odak_kimlik:["kastilya"], devlet:"kastilya", d:"Kardeşi Juan'ın Navarra'da evlenmek için ülkede olmamasından yararlanan Aragonlu infante Enrique, Tordesillas'ta II. Juan'ın şahsına el koydu. Darbe 'Aragon infanteleri' arasındaki bölünmeyi açığa çıkardı ve bu boşlukta kralın gözdesi Álvaro de Luna kraliyet otoritesinin fiilî taşıyıcısı olarak yükseldi.", kaynak:"V. Álvarez Palenzuela, \"Juan II de Castilla\", RAH DB~e (biografias/25005)" },
{ t:"1423-01-01", gun:"yalnız yıl (RAH: Viana prensliği unvanı ve Pamplona Birlik İmtiyazı, ikisi de 1423)", b:"Viana prensliği kuruldu, Pamplona 'Birlik İmtiyazı' ile tek belediye oldu", tur:"idari", onem:3, dunya:1, kapsam:"ic", etiket:["idari","navarra-kurumlar","konu-idari"], yer_id:"Pamplona", devlet:"navarra", d:"III. Carlos, torunu Carlos için Navarra veliahtlarına özgü 'Viana prensi' unvanını yarattı. Aynı yıl çıkardığı Birlik İmtiyazı (Privilegio de la Unión) ile birbiriyle sürekli çatışan Pamplona'nın ayrı kent birimlerini tek bir belediye meclisi altında birleştirdi; bu, bugünkü Pamplona'nın kuruluş belgesi sayılır.", kaynak:"V. Á. Álvarez Palenzuela, \"Carlos III\", RAH DB~e (biografias/9671)" },
{ t:"1425-09-08", gun:"8 Eylül 1425 III. Carlos'un ölümü (RAH künyesi ve II. Juan biyografisi); RAH I. Blanca biyografisi 7 Eylül der — çelişki bildirilir", b:"I. Blanca ve eşi Juan (Aragonlu) Navarra tahtına geçti", tur:"hukumdar", onem:4, dunya:1, kapsam:"ic", etiket:["hukumdar","navarra-trastamara","konu-siyasi"], yer_id:"Pamplona", devlet:"navarra", d:"III. Carlos'un Olite'de ölümüyle kızı Blanca kraliçe, eşi Aragon infantesi Juan ise kral ilan edildi; taç giyme 1429'a dek ertelendi. Juan Navarra'yı Kastilya'daki 'infanteler' mücadelesinin üssü olarak kullandı ve krallığı Kastilya savaşlarına sürükledi; 1419 evlilik sözleşmesinin belirsizliği ileride oğlu Carlos ile veraset kavgasının tohumu oldu.", kaynak:"J. Utrilla Utrilla, \"Juan II de Aragón y de Navarra\", RAH DB~e (biografias/25004); M. L. Bueno Domínguez, \"Blanca I de Navarra\", RAH DB~e 6953; V. Á. Álvarez Palenzuela, \"Carlos III\", RAH DB~e 9671" },
{ t:"1431-01-01", gun:"yalnız yıl (TDV `girnata`: 1431); gün yok", b:"Kastilya Kralı II. Juan Gırnata'yı kuşattı, şehre giremedi", tur:"savas", onem:3, dunya:1, kapsam:"dis", etiket:["savas","gırnata-savunmasi","konu-askeri"], yer_id:"Granada", devletler:["granada","kastilya"], d:"IX. Muhammed'in saltanatında taht iddiacısı Yûsuf b. Mevl ve ona bağlı bir grup Gırnatalının kışkırtmasıyla Kastilya Kralı II. Juan Gırnata'yı kuşattı. Halkın da katıldığı güçlü direniş karşısında Kastilya ordusu şehre giremedi.", kaynak:"TDV `girnata`" },
{ t:"1432-01-27", gun:"23 Cemâziyelevvel 835 / 27 Ocak 1432 — TDV `nasriler` tam gün", b:"Kastilya'nın şartlarını kabul eden IV. Yûsuf tahta geçirildi", tur:"hukumdar", onem:3, dunya:1, kapsam:"dis", etiket:["hukumdar","kastilya-himayesi","konu-siyasi"], yer_id:"Granada", devletler:["granada","kastilya"], d:"IX. Muhammed, tahtını geri almasına yardım eden Kastilya'nın hâkimiyet tanıma, yıllık vergi ve esir iadesi taleplerini reddetti. Bunun üzerine Kastilya bu şartları kabul eden IV. Yûsuf'u tahta çıkardı; ancak IV. Yûsuf altı ay sonra ölünce Mâleka'ya çekilmiş olan IX. Muhammed üçüncü kez tahta döndü.", kaynak:"TDV `nasriler`" },
{ t:"1441-05-01", gun:"1 Mayıs 1441 (RAH, II. Juan biyografisi); Blanca biyografisi künyesi yalnız 'V.1441'", b:"I. Blanca öldü — Juan tahtı bırakmadı, veraset kavgası başladı", tur:"kriz", onem:4, dunya:1, kapsam:"ic", etiket:["kriz","navarra-ic-savasi","konu-siyasi"], yer_id:"Pamplona", devlet:"navarra", d:"Kraliçe Blanca'nın Santa María de Nieva'da ölümünden sonra Navarra yasalarına göre taç oğlu Viana prensi Carlos'a geçmeliydi; ancak Blanca vasiyetinde oğlundan babasının rızası olmadan tahtı istememesini dilemişti. Juan kral unvanını bırakmadı; Navarra, Carlos'u destekleyen beaumontlular ile Juan'ı destekleyen agramontlular diye iki kampa bölündü.", kaynak:"J. Utrilla Utrilla, \"Juan II de Aragón y de Navarra\", RAH DB~e 25004; M. L. Bueno Domínguez, \"Blanca I de Navarra\", RAH DB~e 6953" },
{ t:"1445-05-19", gun:"19 Mayıs 1445 (RAH, iki biyografide aynı)", b:"Olmedo Savaşı — Aragon infanteleri Kastilya'dan tasfiye edildi", tur:"savas", onem:4, dunya:1, kapsam:"ic", etiket:["savas","aragon-infanteleri","konu-askeri"], yer_id:"", odak_kimlik:["kastilya"], devlet:"kastilya", d:"Kastilya'da iktidarı yeniden ele geçirmek için orduyla giren infante Juan (Navarra kralı) ve kardeşi Enrique, Olmedo'da II. Juan, veliaht Enrique ve Álvaro de Luna'nın kuvvetlerine yenildi. Zafer Aragonlu Trastámaraların Kastilya'daki nüfuzunu bitirdi, ama gücü krala değil bir soylular birliğine taşıdı.", kaynak:"V. Álvarez Palenzuela, \"Juan II de Castilla\", RAH DB~e 25005; L. Suárez Fernández, \"Enrique IV\", RAH DB~e 15077" },
{ t:"1451-10-23", gun:"23 Ekim 1451 (RAH)", b:"Aibar Savaşı — Navarra iç savaşında Viana prensi esir düştü", tur:"savas", onem:4, dunya:1, kapsam:"ic", etiket:["savas","navarra-ic-savasi","konu-askeri"], yer_id:"Pamplona", devlet:"navarra", d:"Babası tarafından naiplikten uzaklaştırılan Viana prensi Carlos, beaumontlularla ve Kastilya'nın desteğiyle silaha sarıldı; Aibar'da agramontlu kuvvetlere yenilerek esir alındı. Savaş, Navarra'yı yıllarca sürecek bir iç savaşa sokan agramontlu-beaumontlu çekişmesini kanlı biçimde kurumsallaştırdı.", kaynak:"J. Utrilla Utrilla, \"Juan II de Aragón y de Navarra\", RAH DB~e (biografias/25004)" },
{ t:"1453-06-02", gun:"2 Haziran 1453 (RAH, Álvaro de Luna biyografisi künyesi); RAH II. Juan biyografisi 3 Haziran der — çelişki bildirilir", b:"Kontostabl Álvaro de Luna Valladolid'de idam edildi", tur:"siyaset", onem:3, dunya:1, kapsam:"ic", etiket:["siyaset","alvaro-de-luna","konu-siyasi"], yer_id:"", odak_kimlik:["kastilya"], devlet:"kastilya", d:"Otuz yıl II. Juan'ın adına Kastilya'yı yöneten kontostabl ve Santiago tarikatı ustası Álvaro de Luna, soyluların ve kraliçenin baskısıyla gözden düşürülüp Valladolid'de kafası kesilerek idam edildi. Kral kararı iki hafta sonra ülkeye resmen duyurdu; kendisi de ertesi yıl öldü.", kaynak:"V. Á. Álvarez Palenzuela, \"Álvaro de Luna\", RAH DB~e (biografias/27650); V. Álvarez Palenzuela, \"Juan II de Castilla\", RAH DB~e 25005" },
{ t:"1454-07-21", gun:"21 Temmuz 1454 (RAH II. Juan künyesi); RAH IV. Enrique biyografisi 22 Temmuz der — çelişki bildirilir", b:"II. Juan öldü, IV. Enrique Kastilya tahtına çıktı", tur:"hukumdar", onem:3, dunya:1, kapsam:"ic", etiket:["hukumdar","kastilya-taht","konu-siyasi"], yer_id:"", odak_kimlik:["kastilya"], devlet:"kastilya", d:"II. Juan Valladolid'de öldü; yerine ilk evliliğinden oğlu IV. Enrique geçti. İkinci evliliğinden doğan küçük çocukları Alfonso ve İsabel, anneleriyle Arévalo'ya gönderildi; bu üvey kardeşler sonraki on yıllarda taht mücadelesinin odağı olacaktı.", kaynak:"V. Álvarez Palenzuela, \"Juan II de Castilla\", RAH DB~e 25005; L. Suárez Fernández, \"Enrique IV\", RAH DB~e 15077" },
{ t:"1455-12-03", gun:"3 Aralık 1455, Barcelona (RAH)", b:"Barcelona kararı — Juan, Viana prensini mirastan çıkarıp tahtı Leonor'a verdi", tur:"hanedan", onem:3, dunya:1, kapsam:"ic", etiket:["hanedan","navarra-ic-savasi","konu-siyasi"], yer_id:"Barselona", devlet:"navarra", d:"Juan, Barcelona'da imzaladığı düzenlemeyle oğlu Carlos'u ve büyük kızı Blanca'yı Navarra tahtından yoksun bırakıp küçük kızı Leonor ile eşi Foix kontu IV. Gaston'u vâris ve naip yaptı. Karar Navarra'yı Foix hanedanına bağlayan yolu açtı, ama beaumontluların direnişini de uzattı.", kaynak:"J. Utrilla Utrilla, \"Juan II de Aragón y de Navarra\", RAH DB~e 25004; E. Ramírez Vaquero, \"Leonor de Navarra\", RAH DB~e 25703" },
{ t:"1461-09-23", gun:"23 Eylül 1461, Barcelona (RAH)", b:"Viana prensi Carlos Barcelona'da öldü", tur:"olum", onem:3, dunya:1, kapsam:"ic", etiket:["olum","navarra-ic-savasi","konu-siyasi"], yer_id:"Barselona", devlet:"navarra", d:"Navarra tahtının meşru vârisi sayılan ve Katalonya'da babasına karşı bir direniş simgesine dönüşen Viana prensi Carlos, Barcelona'da veremden beklenmedik biçimde öldü. Ölümü zehirlenme söylentileriyle efsaneleşti; Navarra'da meşruiyet davasının, Katalonya'da ise II. Juan'a karşı iç savaşın bayrağı oldu.", kaynak:"J. Utrilla Utrilla, \"Juan II de Aragón y de Navarra\", RAH DB~e (biografias/25004)" },
{ t:"1462-01-01", gun:"Haziran 1462 (II. Juan'ın Katalonya'ya girişi, Balaguer'in alınması — GEC); gün kaynakta yok", b:"Katalan İç Savaşı başladı (1462–1472)", tur:"isyan", onem:4, dunya:1, kapsam:"ic", etiket:["isyan","katalan-ic-savasi","konu-siyasi"], yer_id:"", odak_kimlik:["aragon"], devlet:"aragon", d:"Veliaht Carlos de Viana'nın 1461'de ölümü ve Vilafranca uzlaşmasının kralın Katalonya'ya izinsiz girmesini yasaklaması üzerine gerginlik savaşa döndü. II. Juan Haziran 1462'de Katalonya'ya girince Principat Konseyi onu kamu düşmanı ilân edip tahttan düşürdü ve tacı önce Kastilya kralı IV. Enrique'ye, sonra Portekizli Pedro'ya, ardından Anjou'lu René'ye sundu. On yıl süren savaş ülkeyi harap etti.", kaynak:"Gran Enciclopèdia Catalana, `guerra-contra-joan-ii`, `joan-ii-de-catalunya-arago`" },
{ t:"1462-01-01", gun:"yalnız yıl (TDV `nasriler`, `cebelitarik`, `endulus`: 1462); gün yok", b:"Cebelitârık Kastilya'ya düştü, Kuzey Afrika bağlantısı koptu", tur:"toprak-kayip", onem:4, dunya:2, kapsam:"dis", etiket:["toprak-kayip","cebelitarik","konu-askeri"], yer_id:"Cebelitarık (Gibraltar)", devletler:["granada","kastilya"], d:"Sa'd b. Ali'nin barış tekliflerini reddeden Kastilya, ülkeyi büyük ölçüde tahrip ederek 1462'de Cebelitârık'ı aldı; TDV'ye göre şehri Şezûne (Medina Sidonia) dükü ele geçirdi. Mağrib'den yardımın geçtiği son kapının kapanması, kalan Nasrî şehirlerinin tek tek düşmesinin yolunu açtı.", kaynak:"TDV `nasriler` · TDV `cebelitarik` · TDV `endulus`" },
{ t:"1462-05-09", gun:"9 Mayıs 1462 Bayonne'da akdedildi (GEC 'tractat de Baiona'); II. Juan 21 Mayıs'ta Zaragoza'da imzaladı", b:"Bayonne Antlaşması — Rusiyon ve Cerdanya Fransa'ya rehin", tur:"antlasma", onem:4, dunya:1, kapsam:"dis", etiket:["antlasma","rusiyon","konu-siyasi"], yer_id:"", odak_kimlik:["aragon","fransa"], devletler:["aragon","fransa"], d:"Katalonya'nın ayaklanmasından korkan II. Juan, Fransa kralı XI. Louis'den askerî yardım karşılığı 200.000 altın borçlandı. Bayonne'da, borç ödenene dek Rusiyon ve Cerdanya kontluklarının egemenlik hakları, yargısı ve gelirleri Perpignan ile Collioure kaleleriyle birlikte Fransız kralına bırakıldı. Fransızlar 1463'te Perpignan şehrini de işgal etti; bu rehin 1493'e dek sürecek bir kayba dönüştü.", kaynak:"Gran Enciclopèdia Catalana, `tractat-de-baiona`, `perpinya`" },
{ t:"1465-01-01", gun:"yalnız yıl: 870 (1465) (TDV `nasriler`); gün yok", b:"Ebü'l-Hasan Ali babası Sa'd'ı tahttan indirdi", tur:"hukumdar", onem:3, dunya:1, kapsam:"ic", etiket:["hukumdar","nasri-sultanlari","konu-siyasi"], yer_id:"Granada", devlet:"granada", d:"Kastilya'ya vergi ödemeyi kabul etmek zorunda kalan Sa'd b. Ali, oğlu Ebü'l-Hasan Ali tarafından tahttan indirildi. Yeni saltanat, kardeşi Muhammed ez-Zagal ile üç yıllık bir taht kavgasına sahne oldu ve Mâleka çevresi Zagal'ın elinde kaldı.", kaynak:"TDV `nasriler`" },
{ t:"1465-06-05", gun:"5 Haziran 1465 (RAH)", b:"Ávila Farsı — soylular IV. Enrique'yi kukla üzerinden tahttan indirdi", tur:"isyan", onem:4, dunya:1, kapsam:"ic", etiket:["isyan","kastilya-veraset","konu-siyasi"], yer_id:"", odak_kimlik:["kastilya"], devlet:"kastilya", d:"Kralın kızı Juana'nın meşruiyetini reddeden Villena markisi Pacheco, Toledo başpiskoposu Carrillo ve müttefikleri, Ávila surları önüne kurdukları sahnede kralı temsil eden bir kuklayı tahttan indirip on bir yaşındaki üvey kardeş Alfonso'yu 'XII. Alfonso' ilan ettiler. Böylece Kastilya iki kralın çekiştiği bir iç savaşa girdi.", kaynak:"L. Suárez Fernández, \"Enrique IV\", RAH DB~e (biografias/15077)" },
{ t:"1468-09-19", gun:"19 Eylül 1468 Guisando'da tören; mutabakat 18 Eylül Cadalso/Cebreros'ta imzalandı (RAH)", b:"Guisando Boğaları uzlaşması — İsabel veliaht tanındı", tur:"siyaset", onem:4, dunya:2, kapsam:"ic", etiket:["siyaset","kastilya-veraset","konu-siyasi"], yer_id:"", odak_kimlik:["kastilya"], devlet:"kastilya", d:"Asi soyluların kralı Alfonso'nun 5 Temmuz 1468'de ölümünden sonra IV. Enrique, kız kardeşi İsabel'i 'Asturias prensesi' olarak tanıdı; Juana'nın veraset hakkı bu uzlaşmayla yok sayıldı. İsabel'in bir yıl sonra kralın rızası olmadan Aragon veliahdı Fernando ile evlenmesi uzlaşmayı bozdu, ama İsabel'in tahta giden hukuki dayanağı burada kuruldu.", kaynak:"L. Suárez Fernández, \"Enrique IV\", RAH DB~e (biografias/15077)" },
{ t:"1472-10-24", gun:"24 Ekim 1472 (GEC)", b:"Pedralbes Kapitülasyonu — Barselona teslim oldu, iç savaş bitti", tur:"antlasma", onem:4, dunya:1, kapsam:"ic", etiket:["antlasma","katalan-ic-savasi","konu-siyasi"], yer_id:"Barselona", devlet:"aragon", d:"II. Juan ile Barselona temsilcileri Pedralbes manastırında barış imzaladı. Kral genel af ilân etti, Katalan kurumlarını 1461 yazındaki hukukî durumuna döndürdü ve savaşın asıl sebebi olan Vilafranca uzlaşmasını geçersiz kıldı. Ancak Rusiyon ve Cerdanya Fransız işgalinde kaldı.", kaynak:"Gran Enciclopèdia Catalana, `capitulacio-de-pedralbes`" },
{ t:"1475-01-01", gun:"Mart 1475 (GEC 'Joan II': 'Perpinyà es lliurà pel març del 1475'); gün kaynakta yok", b:"Perpignan Fransızlara teslim oldu — Rusiyon kaybedildi", tur:"toprak-kayip", onem:3, dunya:1, kapsam:"dis", etiket:["toprak-kayip","rusiyon","konu-askeri"], yer_id:"", odak_kimlik:["aragon","fransa"], devletler:["aragon","fransa"], d:"1473'te geçici olarak Fransız garnizonundan kurtulan Perpignan, XI. Louis'nin 1474'teki yeni kuşatmasına uzun süre direndi; halkı açlıktan fare yemek zorunda kaldı. Şehir sonunda teslim oldu ve II. Juan ona 'en sadık' unvanını verdi. Rusiyon ve Cerdanya 1493 Barselona antlaşmasına dek Fransa'da kaldı.", kaynak:"Gran Enciclopèdia Catalana, `joan-ii-de-catalunya-arago`, `perpinya`" },
{ t:"1476-03-01", gun:"1 Mart 1476 (RAH)", b:"Toro Savaşı — Kastilya veraset savaşında İsabel tarafı üstün geldi", tur:"savas", onem:4, dunya:2, kapsam:"dis", etiket:["savas","kastilya-veraset-savasi","konu-askeri"], yer_id:"", odak_kimlik:["kastilya","portekiz"], devletler:["kastilya","portekiz"], d:"IV. Enrique'nin ölümünden sonra kızı Juana Trujillo'da kraliçe ilan edilmiş ve dayısı Portekiz kralı V. Afonso ile nişanlanmıştı; Portekiz ordusu Kastilya'ya girdi. Fernando'nun Toro'da kazandığı zafer, soyluların ve kentlerin büyük kısmını İsabel'in yanında tuttu ve savaşın gidişatını belirledi.", kaynak:"L. Suárez Fernández, \"Isabel I\", RAH DB~e (biografias/24039)" },
{ t:"1478-01-01", gun:"yalnız yıl (TDV `nasriler`: 1478); gün yok", b:"Ebü'l-Hasan Ali, Katolik Krallar'ın haraç ve hâkimiyet talebini reddetti", tur:"diplomasi", onem:4, dunya:1, kapsam:"dis", etiket:["diplomasi","gırnata-savasi","konu-siyasi"], yer_id:"Granada", devletler:["granada","kastilya","aragon"], d:"Isabella ve Ferdinand, Ebü'l-Hasan Ali'den vergiyi artırmasını ve üstünlüklerini tanımasını istedi. Sultan talebi reddedip vergiyi tamamen keseceğini bildirerek savaşla tehdit edince iki krallık Nasrî ülkesine genel bir taarruz başlattı; Gırnata'nın son savaşının siyasi başlangıcı budur.", kaynak:"TDV `nasriler`" },
{ t:"1479-01-19", gun:"19 Ocak 1479 II. Juan'ın ölümü (RAH); Leonor 12 Şubat 1479'da öldü", b:"II. Juan öldü — Leonor on beş günlük kraliçe, taç Foix'lı Francisco Febo'ya geçti", tur:"hukumdar", onem:4, dunya:1, kapsam:"ic", etiket:["hukumdar","navarra-foix","konu-siyasi"], yer_id:"Pamplona", devlet:"navarra", d:"II. Juan'ın Barcelona'da ölümüyle Aragon tacı oğlu Fernando'ya, Navarra ise kızı Leonor'a kaldı; Leonor Cortes'in yeminini aldıktan yaklaşık on beş gün sonra öldü. Taç, Foix kontluğunu da taşıyan küçük torunu Francisco Febo'ya geçti; böylece Navarra ile Aragon'un yolları ayrıldı ve Navarra Pirene ötesi Foix-Béarn topraklarına bağlandı.", kaynak:"E. Ramírez Vaquero, \"Leonor de Navarra\", RAH DB~e (biografias/25703); J. Utrilla Utrilla, \"Juan II de Aragón y de Navarra\", RAH DB~e 25004" },
{ t:"1479-09-04", gun:"4 Eylül 1479 imza; Portekiz onayı 8 Eylül 1479, Katolik Krallar onayı 6 Mart 1480 Toledo", b:"Alcáçovas Antlaşması — Kastilya veraset savaşı bitti, Atlantik paylaşıldı", tur:"antlasma", onem:4, dunya:3, kapsam:"dis", etiket:["antlasma","kastilya-veraset-savasi","konu-siyasi"], yer_id:"", odak_kimlik:["ispanya","portekiz"], devletler:["ispanya","portekiz"], d:"Alcáçovas'ta imzalanan antlaşmayla V. Afonso Kastilya tahtı iddiasından, Katolik Krallar da Portekiz tahtından vazgeçti; Katolik Kralların kızı İsabel'in Portekiz veliahdının oğluyla evlenmesi kararlaştırıldı. Kanarya Adaları Kastilya'ya kalırken Portekiz, Gine ve bulunmuş-bulunacak Atlantik topraklarında seyrüsefer tekelini tanıttı; bu, deniz alanlarının nüfuz bölgelerine ilk bölüşümüdür ve Tordesillas'ın öncülüdür. (Kastilya künyesi 1479-01-20'de bittiği için madde ispanya'ya bağlandı.)", kaynak:"J. L. Ferreira, \"Treaty of Alcáçovas-Toledo\", Enciclopédia Virtual da Expansão Portuguesa (FCSH – Universidade Nova de Lisboa, eve.fcsh.unl.pt); L. Suárez Fernández, \"Isabel I\", RAH DB~e 24039 (yalnız yıl)" },
{ t:"1483-03-20", gun:"Safer 888 / Mart 1483 (TDV); gün 20-21 Mart 1483: RAH Historia Hispánica (Boabdil biyografisi, Hechos). TDV gün vermediği için gün RAH'tan", b:"Zagal, Mâleka dağlarında (Ajarquía) Kastilya akıncı ordusunu bozguna uğrattı", tur:"savas", onem:3, dunya:1, kapsam:"dis", etiket:["savas","gırnata-savasi","konu-askeri"], yer_id:"Málaga", devletler:["granada","ispanya"], d:"Hâme'yi (Alhama) işgal edip Levşe'ye (Loja) saldıran ama şehir halkının direnişiyle geri çekilen Ferdinand'ın Mâleka üzerine gönderdiği ordu, Muhammed ez-Zagal karşısında ağır bir yenilgiye uğradı. Bu zafer, yeğeni Ebû Abdullah'ı (Boabdil) Lucena seferine özendirdi.", kaynak:"TDV `nasriler` · Real Academia de la Historia, Historia Hispánica (DB~e), 'Muhammad XI (Boabdil)' biyografisi, Hechos: 1483 20/iii-21/iii" },
{ t:"1484-01-01", gun:"gün yok: RAH 'Haziran 1484, Lescar katedrali'", b:"Kraliçe Catalina, Jean d'Albret ile evlendi — Albret hanedanı", tur:"hanedan", onem:4, dunya:1, kapsam:"ic", etiket:["hanedan","navarra-albret","konu-siyasi"], yer_id:"Pamplona", devlet:"navarra", d:"Kardeşi Francisco Febo'nun 1483'teki ölümüyle tahta geçen Catalina de Foix, Lescar katedralinde Albret senyörü Jean ile evlendi. Evlilik Navarra, Foix, Béarn ve Albret topraklarını tek hanedanda topladı; ama küçük krallığı İspanya ile Fransa arasında daha da kırılgan bir konuma itti. Çift ancak 1494'te Pamplona'da taç giyebildi.", kaynak:"C. Juanto Jiménez, \"Juan III de Albret\", RAH DB~e (biografias/1671)" },
{ t:"1485-01-01", gun:"yalnız yıl: 890 (1485) (TDV `nasriler`); gün yok", b:"Ebü'l-Hasan Ali tahtı kardeşi XII. Muhammed ez-Zagal'a bıraktı", tur:"hukumdar", onem:3, dunya:1, kapsam:"ic", etiket:["hukumdar","nasri-sultanlari","konu-siyasi"], yer_id:"Granada", devlet:"granada", d:"Oğlu Ebû Abdullah Lucena'da esir düştükten sonra Gırnata'ya dönen Ebü'l-Hasan Ali, kardeşi Muhammed ez-Zagal lehine tahttan feragat etti. Aynı dönemde Katolik Krallar esirleri Ebû Abdullah'ı kendi hâkimiyetlerini tanıması şartıyla amcasına karşı salıverdi; ülke iki sultan arasında bölündü.", kaynak:"TDV `nasriler`" },
{ t:"1486-05-29", gun:"Levşe'de çarpışmalar 20-29 Mayıs 1486, teslim 29 Mayıs: RAH Historia Hispánica (Boabdil, Hechos). TDV düşüşü tarihlemez, yalnız Mâleka kuşatmasından önce olduğunu söyler", b:"Levşe (Loja) teslim oldu, Ebû Abdullah ikinci kez esir düştü", tur:"toprak-kayip", onem:3, dunya:1, kapsam:"dis", etiket:["toprak-kayip","gırnata-savasi","konu-askeri"], yer_id:"Loja", devletler:["granada","ispanya"], d:"Kastilya kuvvetleri, Zagal ile Ebû Abdullah arasındaki bölünmeden yararlanarak batı sınırının kilidi Levşe'ye yüklendi; bir haftalık çarpışmadan sonra şehir teslim oldu ve Ebû Abdullah ikinci kez esir alındı. Levşe'nin düşüşüyle Mâleka kuşatmasının yolu açıldı.", kaynak:"Real Academia de la Historia, Historia Hispánica (DB~e), 'Muhammad XI (Boabdil)' biyografisi, Hechos: 1486 20/v-29/v · TDV `nasriler` · TDV `endulus`" },
{ t:"1487-01-01", gun:"yalnız yıl (TDV `endulus`: 1487); gün yok", b:"Ebû Abdullah Osmanlı Sultanı II. Bayezid'den yardım istedi", tur:"diplomasi", onem:3, dunya:2, kapsam:"dis", etiket:["diplomasi","osmanli-endulus","konu-siyasi"], yer_id:"Granada", devlet:"granada", d:"Şehirleri birer birer kaybeden Gırnata emîri Ebû Abdullah, 1487'de II. Bayezid'e elçi göndererek Katolik Krallar'a karşı yardım istedi. Cem Sultan meselesi ve Memlûklerle uğraşan Bayezid asker gönderemedi; papaya ve Ferdinand'a mektup yazarak Endülüs Müslümanlarının sıkıştırılmamasını istemekle yetindi.", ic_not_d:"Osmanlı çekirdek kronolojidir, künyesi yok — madde yalnız granada künyesine bağlandı.", kaynak:"TDV `endulus` (Endülüs-Osmanlı Münasebetleri bölümü) · TDV `nasriler`" },
{ t:"1487-08-18", gun:"27 Şâban 892 / 18 Ağustos 1487 — TDV `maleka` tam gün (kuşatma başlangıcı 7 Mayıs 1487: RAH)", b:"Mâleka kanlı bir kuşatmadan sonra düştü", tur:"toprak-kayip", onem:4, dunya:2, kapsam:"dis", etiket:["toprak-kayip","gırnata-savasi","konu-askeri"], yer_id:"Málaga", devletler:["granada","ispanya"], d:"Zagal'ın elindeki Mâleka (Malaga), Kuzey Afrika hükümdarlarından ve Memlûk Sultanı Kayıtbay'dan beklenen yardım gelmeyince uzun ve kanlı bir kuşatmanın ardından teslim oldu. Nasrîlerin ikinci başşehri ve başlıca limanının kaybı, krallığı denizden büyük ölçüde kopardı.", kaynak:"TDV `maleka` · TDV `nasriler` · RAH Historia Hispánica (Boabdil, Hechos: 1487 7/V kuşatma başı)" },
{ t:"1489-12-04", gun:"4 Aralık 1489 — RAH Historia Hispánica (Boabdil, Hechos); TDV Besta (Baza) için gün vermez", b:"Besta (Baza) teslim oldu, Zagal bütün topraklarını bıraktı", tur:"toprak-kayip", onem:4, dunya:1, kapsam:"dis", etiket:["toprak-kayip","gırnata-savasi","konu-askeri"], yer_id:"Granada", devletler:["granada","ispanya"], d:"Uzun kuşatmadan sonra Besta (Baza) teslim oldu ve Muhammed ez-Zagal kendi elindeki bütün toprakların teslimi için pazarlığa girişti. Böylece Nasrî ülkesinden geriye yalnız Ebû Abdullah'ın elindeki Gırnata ve çevresi kaldı.", kaynak:"Real Academia de la Historia, Historia Hispánica (DB~e), 'Muhammad XI (Boabdil)' biyografisi, Hechos: 1489 4/xii · TDV `endulus` (1490 baharına kadar Gırnata dışı şehirlerin kaybı)" },
{ t:"1490-01-01", gun:"Şubat 1490 (TDV `meriye`); gün yok → YYYY-01-01. Not: teslim pazarlığı 1489 sonunda Baza ile birlikte yürüdü (RAH)", b:"Kastilya ordusu Meriye'ye (Almería) girdi", tur:"toprak-kayip", onem:3, dunya:1, kapsam:"dis", etiket:["toprak-kayip","gırnata-savasi","konu-askeri"], yer_id:"Almería", devletler:["granada","ispanya"], d:"Zagal'ın teslim anlaşması çerçevesinde Kastilya ordusu Şubat 1490'da Meriye'ye girdi. Halka can, mal ve din güvencesi verilmişse de Ulucami başta olmak üzere mescitler kiliseye çevrildi ve Müslümanlar çevre köylere çıkarıldı.", kaynak:"TDV `meriye`" },
{ t:"1491-10-25", gun:"⚠️ GÜN ÇELİŞKİSİ: TDV `nasriler` '25 Ekim 1491 tarihli antlaşma' der (birincil → t bu); RAH Historia Hispánica 'Se firma el acuerdo… 25/xi/1491' (25 Kasım) der. TDV `girnata` yalnız '1491'. Koordinatör hükmü gerekir", b:"Gırnata'nın teslim antlaşması imzalandı", tur:"antlasma", onem:5, dunya:3, kapsam:"dis", etiket:["antlasma","gırnata-savasi","konu-siyasi"], yer_id:"Granada", devletler:["granada","ispanya"], d:"1491 ilkbaharından beri toplarla kuşatılan, kıtlık ve salgınla tükenen Gırnata'da Ebû Abdullah halkın canına, malına ve dinine dokunulmaması şartıyla teslimi kabul etti. Antlaşma yahudilere de aynı güvenceyi tanıyor, Ebû Abdullah'a Büşürât'ta (Alpujarras) bir bölge ayırıyordu. Şartlara göre İspanyol kuvvetleri Ocak 1492'nin başında şehre girdi; II. Bayezid ve Kayıtbay'dan beklenen yardım gelmemişti.", kaynak:"TDV `nasriler` · TDV `girnata` · Real Academia de la Historia, Historia Hispánica (DB~e), 'Muhammad XI (Boabdil)', Hechos: 1491 25/xi" },
{ t:"1515-06-11", gun:"11 Haziran 1515 Burgos Cortes'ine bildirim; kral 7 Temmuz 1515'te aynı Cortes'te teyit etti (Adot Lerga)", b:"Burgos Cortes'i — Yukarı Navarra Kastilya tacına katıldı", tur:"birlesme", onem:5, dunya:2, kapsam:"dis", etiket:["birlesme","navarra-ilhak","konu-siyasi"], yer_id:"Burgos", devletler:["ispanya","navarra"], d:"1512'de fethettiği Navarra'yı bir süre Aragon'a bağlı tutan Katolik Fernando, Alba dükü aracılığıyla Burgos'taki Kastilya Cortes'ine krallığı kızı Juana'ya bırakıp 'Kastilya, León ve Granada tacına' kattığını bildirdi. Navarra yasalarını ve kurumlarını korudu, ama Kastilya Kraliyet Konseyi'ne bağlandı; Navarra Cortes'i 1516'da ilişkiyi eşit iki krallık birliği olarak yorumladı. Albret hanedanı Pirene'nin kuzeyindeki Aşağı Navarra'da krallık iddiasını sürdürdü.", kaynak:"Á. Adot Lerga, \"La vinculación del Reino de Navarra a Castilla según la doble interpretación de las Cortes Generales de ambos territorios\", Araucaria 15/29 (2013), s. 255-263" },
{ t:"1521-06-30", gun:"30 Haziran 1521 (RAH)", b:"Noáin Savaşı — Albret'lerin Navarra'yı geri alma girişimi çöktü", tur:"savas", onem:4, dunya:1, kapsam:"dis", etiket:["savas","navarra-ilhak","konu-askeri"], yer_id:"Pamplona", devletler:["navarra","ispanya"], d:"Navarra'yı geri almak için birkaç girişimde bulunan II. Henri d'Albret'nin (Enrique II) kuvvetleri, Noáin'de İmparator V. Karl'ın ordusuna kesin biçimde yenildi; ardından Kastilya kuvvetleri Béarn'a ve Albret topraklarına misilleme seferi düzenledi. Yenilgi, Pirene'nin güneyindeki Navarra'nın kurtarılması umutlarına fiilen son verdi.", kaynak:"C. Juanto Jiménez, \"Enrique II de Albret\", RAH DB~e (biografias/15074)" },
{ t:"1527-01-01", gun:"gün yok: RAH 'Eylül 1527'", b:"Aşağı Navarra (Ultrapuertos) Albret yönetimine döndü", tur:"toprak-kazanc", onem:3, dunya:1, kapsam:"dis", etiket:["toprak-kazanc","asagi-navarra","konu-siyasi"], yer_id:"Pamplona", devletler:["navarra","ispanya"], d:"Pirene'nin kuzeyindeki 'altıncı merindad' Ultrapuertos'ta yeniden kurulan Kastilya yönetimi, Eylül 1527'de Aşağı Navarra soylularının bölgeyi II. Henri d'Albret adına ele geçirmesiyle çöktü. V. Karl bölgeyi açık bir feragat olmaksızın fiilen bıraktı; Albret'ler burada Navarra'nın kurumlarını taklit eden bir yönetimle krallık unvanlarını 1620'ye dek sürdürdüler.", kaynak:"C. Juanto Jiménez, \"Enrique II de Albret\", RAH DB~e (biografias/15074)" },
{ t:"1560-12-25", gun:"25 Aralık 1560, Noel Şükran Ayini, Pau (RAH, Bordenave'ye atıfla)", b:"Kraliçe III. Juana (Jeanne d'Albret) Kalvinizmi açıkça benimsedi", tur:"din", onem:4, dunya:2, kapsam:"ic", etiket:["din","reform-kalvinizm","konu-dini"], yer_id:"Pamplona", devlet:"navarra", d:"1555'ten beri eşi Antoine de Bourbon ile Navarra ve Béarn'ı yöneten III. Juana, Pau'da Noel ayininde Roma kilisesinden ayrılıp Reform kilisesine katıldığını açıkladı. Kararı Béarn ve Aşağı Navarra'yı Fransız Protestanlığının kalesine çevirdi; 1563 sinodu, 1566 kilise nizamnameleri ve Kutsal Kitap çevirileriyle krallık dinî bakımdan dönüştürüldü.", kaynak:"A. Floristán Imízcoz, \"Juana III de Albret\", RAH DB~e (biografias/24948)" },
{ t:"1571-01-01", gun:"yalnız yıl (1571)", b:"Leizarraga'nın Baskça Yeni Ahit çevirisi yayımlandı", tur:"kultur", onem:2, dunya:2, kapsam:"ic", etiket:["kultur","bask-dili","konu-kultur"], yer_id:"Pamplona", devlet:"navarra", d:"III. Juana'nın bizzat desteklediği Reform programı çerçevesinde Joanes Leizarraga, Yeni Ahit'i Baskçaya çevirdi. Çeviri, Reform'un halk dilinde yayılması politikasının parçasıydı ve Bask dilinin yazılı geleneğinde önemli bir yer tuttu; aynı dönemde Béarn diline de bir çeviri hazırlandı.", kaynak:"A. Floristán Imízcoz, \"Juana III de Albret\", RAH DB~e (biografias/24948)" },
{ t:"1572-06-09", gun:"9 Haziran 1572, Paris (RAH)", b:"III. Juana öldü — oğlu Henri (III. Enrique) Navarra kralı oldu", tur:"hukumdar", onem:4, dunya:2, kapsam:"ic", etiket:["hukumdar","navarra-bourbon","konu-siyasi"], yer_id:"Pamplona", devlet:"navarra", d:"Oğlu Henri ile Marguerite de Valois'nın evliliğini hazırlamak için Paris'te bulunan III. Juana, düğünü göremeden öldü. Navarra tahtı Bourbon hanedanından oğlu Henri'ye geçti; aynı yaz Saint-Barthélemy katliamından sağ kurtulan Henri, 1589'da Fransa tahtına IV. Henri olarak çıktı ve Navarra ile Fransa taçları aynı başta birleşti.", kaynak:"A. Floristán Imízcoz, \"Juana III de Albret\", RAH DB~e (biografias/24948)" }
];
